[29] = {"엘룬아라 호수의 시험", {"엘룬아라 호수에서 제단 구슬을 찾은 후 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.","","그런 다음 제단에 있는 타자리와 대화를 하면 이 시험을 통과하게 됩니다."}},
