[263] = {"왕국 수호", {"남쪽 경비탑의 산악경비대 월뱅이 가루바위일족 주술사 10명과 가루바위일족 뼈다귀싸움꾼 10명을 처치해 달라고 부탁했습니다."}},
[264] = {"영원한 이별", {"은빛소나무 숲에 있는 유리브의 무덤에 클라리스의 펜던트를 가져다 놓아야 합니다."}},
[265] = {"계속되는 조사", {"다른 마을 주민에게서 의문의 남자에 대한 정보를 알아봐야 합니다."}},
[266] = {"여관에서의 조사", {"여관에서 의문의 남자에 대한 정보를 얻으십시오."}},
[267] = {"트로그의 위협", {"남쪽 경비탑에 있는 경비대장 루겔퍼스에게 트로그의 단단한 이빨 8개를 가져가야 합니다."}},
[268] = {"스벤에게 돌아가기", {"완성된 지터스의 일지를 가지고 스벤에게 돌아가야 합니다."}},
[269] = {"지혜의 추구", {"스톰윈드에 있는 주교 파딩에게 완성된 지터스의 일지를 보여 줘야 합니다."}},
[270] = {"저주받은 함대", {"저습지에 있는 메네실 항구로 가서 글로린 스틸브로우와 대화해야 합니다."}},
[271] = {"바이린의 복수", {"늙은곰 수티를 처치하고 그 결과를 순찰자의 오두막에 있는 풋내기 다릴에게 보여 주어야 합니다."}},
[272] = {"바다표범의 시험", {"민첩성의 바다 펜던트 반쪽과 인내의 바다 펜던트 반쪽을 찾아야 합니다. 달의 숲 주민들에게서 이 물건들이 있을 만한 위치에 대한 단서를 얻으십시오.","","두 개의 반쪽을 찾아 바다표범의 펜던트를 만들어야 합니다. 반드시 레물로스의 제단 근처로 와야만 하나로 합칠 수 있습니다.","","완성된 바다표범의 펜던트를 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 가져가십시오."}},
[273] = {"물자 공급 재개", {"훌다르와 대화하십시오."}},
[274] = {"어둠의 전조", {"애실런 스톤스머크가 선임기술자 힌더바이르에게 돌아가 새로 발견한 사실을 알려 줄 것을 부탁했습니다."}},
[275] = {"대지의 상처", {"수렁이끼괴물 12마리를 처치한 다음 저습지에 있는 신록의수호자 레시엘에게 돌아가야 합니다."}},
[276] = {"파괴의 손길", {"이끼가죽 놀 15마리와 이끼가죽일족 싸움꾼 10마리를 처치한 다음 저습지에 있는 신록의수호자 레시엘에게 돌아가야 합니다."}},
[277] = {"화재 예방", {"신록의수호자 레시엘에게 조잡한 부싯돌 9개를 가져가야 합니다."}},
[278] = {"어둠의 전조", {"선임기술자 힌더바이르가 럴커의 독액, 모그로쉬 수정, 악어 눈물을 모아 달라고 부탁했습니다."}},
[279] = {"멀록과 고블러", {"푸른아가미멀록 12마리와 고블러를 처치하고 그 머리를 손에 넣어야 합니다.","","메네실 항구의 칼 보란에게 고블러의 머리를 가져가야 합니다."}},
[280] = {"어둠의 전조", {"선임기술자 힌더바이르가 댐 밑바닥으로 헤엄쳐 가서 화약통에 중화제를 넣어 섞어 달라고 부탁했습니다."}},
[281] = {"뱃짐 되찾기", {"해안가의 멀록 소굴에서 상자와 통을 찾아 열어봐야 합니다."}},
[282] = {"그렐린의 보고서", {"산악경비대 탈로스와 얘기를 나누십시오."}},
[283] = {"어둠의 전조", {"중화제의 효과가 나타나는 것 같습니다. 선임기술자 힌더바이르에게 돌아가 이 기쁜 소식을 알려 주십시오."}},
[284] = {"계속되는 수색", {"메네실 조각상을 찾아야 합니다."}},
[285] = {"다른 소굴 수색", {"멀록 소굴에서 메네실 조각상을 계속 찾아봐야 합니다."}},
[286] = {"조각상 돌려주기", {"칼 보란에게 메네실 조각상을 가져가야 합니다."}},
[287] = {"서리갈기 소굴", {"서리갈기 소굴을 찾아 서리갈기부족 인간사냥꾼 5마리를 처치한 후 카라노스에 있는 세니르 화이트비어드에게 돌아와야 합니다."}},
[288] = {"제 3함대", {"일등항해사 피츠시몬즈에게 벌꿀술을 한 병 사 줘야 합니다."}},
[289] = {"저주받은 선원", {"저주받은 선원 13명, 저주받은 해병 5명, 그리고 일등항해사 스넬리그를 처치해야 합니다. 메네실 항구에 있는 일등항해사 피츠시몬즈에게 스넬리그의 연초상자를 가져가야 합니다."}},
[290] = {"저주 풀기", {"할린도르 선장을 처치한 후 인트레피드호의 금고 열쇠를 손에 넣어야 합니다.","","그 열쇠를 사용하여 인트레피드호의 잠긴 금고를 열어야 합니다."}},
[291] = {"보고", {"아이언포지에 있는 원로원의원 바린 레드스톤에게 세니르의 보고서를 전달해야 합니다."}},
[292] = {"팔레스의 눈", {"글로린 스틸브로우에게 팔레스의 저주받은 눈을 가져가야 합니다."}},
[293] = {"팔레스의 눈 정화", {"대주교 베네딕투스에게 팔레스의 저주받은 눈을 가져가야 합니다. 베네딕투스는 스톰윈드의 빛의 대성당에 있습니다."}},
[294] = {"오머의 복수", {"웰가르의 발굴현장에 있는 오머 아이언브레이드가 긴송곳니 줄무늬랩터 10마리와 줄무늬랩터 10마리를 처치해 달라고 부탁했습니다."}},
[295] = {"오머의 복수", {"웰가르의 발굴현장에 있는 오머 아이언브레이드가 갈퀴발톱 줄무늬랩터 10마리, 무쇠턱 줄무늬랩터 10마리를 처치해 달라고 부탁했습니다."}},
[296] = {"오머의 복수", {"웰가르의 발굴현장에 있는 오머 아이언브레이드가 살투스를 처치한 후 발톱을 가져다 달라고 부탁했습니다."}},
[297] = {"조각상 모으기", {"마그마 펠휴에게 돌 조각상 8개를 가져가야 합니다."}},
[298] = {"발굴 상황 보고서", {"텔사마의 예른 혼헬름에게 아이언밴드의 상황 보고서를 가져가야 합니다."}},
[299] = {"드러난 과거", {"발굴조사단장 웰가르가 발굴현장을 정리하고 사라진 아도스 조각, 모드르 조각, 골름 조각, 네루 조각을 가져다 달라고 부탁했습니다."}},
[301] = {"아이언포지에 보고", {"발굴조사단장 스톰파이크에게 아이언밴드의 상황 보고서를 가져가야 합니다."}},
[302] = {"아이언밴드에게 화약 지원", {"텔사마의 예른 혼헬름과 대화하십시오."}},
[303] = {"검은무쇠 부족과의 전투", {"던 모드르의 모틀리 가마슨이 검은무쇠 드워프 15명, 검은무쇠 채굴꾼 5명, 검은무쇠 투사 5명, 검은무쇠 폭파병 5명을 처치해 달라고 부탁했습니다."}},
[304] = {"위험한 임무", {"불한당 발가라스를 처치하고 그의 귀걸이를 던 모드르 외곽에 있는 결의의 롱브레이드에게 가져가야 합니다."}},
[305] = {"발굴단을 찾아서", {"타렐 록위버가 발굴 현장으로 가서 메린 록위버를 찾아 달라고 부탁했습니다."}},
[306] = {"발굴단을 찾아서", {"타렐 록위버에게 메린의 편지를 가져가야 합니다."}},
[307] = {"더러운 손", {"은여울 광산에서 광부의 도구 4개를 모아야 합니다.","","그런 다음 산악경비대 스톰파이크에게 돌아가십시오."}},
[308] = {"맥주를 좋아하는 야벤", nil},
[309] = {"화약 운반", {"미란이 발굴 지역까지 무사히 도착할 수 있도록 경호하고 발굴조사단장 아이언밴드에게 가십시오."}},
[310] = {"숙명의 경쟁자", {"카라노스에 있는 썬더브루 양조장의 지하실로 가서 썬더 에일 맥주통을 발리브루 스칼더 맥주통으로 바꿔 놓아야 합니다."}},
[311] = {"말레스에게 돌아가기", {"브루날 마을에 있는 말레스 발리브루에게 썬더 에일 맥주통을 가져다주어야 합니다."}},
[312] = {"툰드라 맥그란의 고기 상자", {"늙은 얼음수염의 동굴에 있는 잃어버린 고기 상자에서 툰드라 맥그란의 말린 고기를 되찾아 와야 합니다."}},
[313] = {"은빛 동굴", {"웬디고 갈기 8개를 모아 조종사 스톤기어에게 가져다주어야 합니다."}},
[314] = {"가축 보호", {"루드라 앰버스틸이 바가쉬를 처치한 후 산양 농장으로 바가쉬의 송곳니를 가지고 오라고 부탁했습니다."}},
[315] = {"최고급 스타우트 맥주", {"브루날 마을에 있는 레욜트 발리브루에게 쉼머위드 6개를 가져다주어야 합니다."}},
[317] = {"증기 전차 공급품 비축", {"멧돼지 고기 4개와 두꺼운 곰 모피 2개를 모아서 스틸그릴의 정비소에 있는 조종사 벨로우피즈에게 가져다주어야 합니다."}},
[318] = {"에버샤인", {"브루날 마을에 있는 레욜트 발리브루에게서 에버샤인 술통을 얻으십시오."}},
[319] = {"에버샤인 얻기", {"얼음발톱흰곰 6마리, 덩치큰 멧돼지 8마리, 눈표범 8마리를 사냥한 다음 브루날 마을에 있는 레욜트 발리브루에게 돌아가십시오."}},
[320] = {"벨로우피즈에게 돌아가기", {"스틸그릴의 정비소에 있는 조종사 벨로우피즈에게 에버샤인 술통을 가져다주어야 합니다."}},
[321] = {"라이트포지 철", {"저습지에 있는 난파된 창공의 물수리호를 찾아야 합니다."}},
[322] = {"신성한 무기", {"스톰윈드에 있는 그리만트 엘모어에게 라이트포지 주괴가 든 상자를 가져가야 합니다."}},
[323] = {"영웅의 진가", {"해골 약탈자 15마리, 해골 치료사 3마리, 해골 문지기 3마리를 처치한 다음 스벤에게 돌아가야 합니다."}},
[324] = {"사라진 주괴", {"라이트포지 주괴 5개를 모은 다음 저습지에 있는 글로린 스틸브로우에게 돌아가야 합니다."}},
[325] = {"무기 완성", {"모벤트 파멸의 불꽃을 그늘숲에 있는 스벤에게 가져가야 합니다."}},
[328] = {"숨겨진 열쇠", {"작은 놋쇠 열쇠로 사서 헤로드의 금고를 열어야 합니다."}},
[329] = {"드러나는 첩자의 정체", {"반란군 야영지에 있는 부관 도렌에게 진흙투성이 쪽지를 가져가야 합니다."}},
[330] = {"정찰 일정", {"하사관 세스먼과 대화해야 합니다."}},
[331] = {"도렌에게 보고하기", {"부관 도렌과 대화해야 합니다."}},
[332] = {"와인 가게 광고", {"갈리나 포도주 상점으로 가서 수제타 갈리나에게 와인 티켓을 주고 와인 한 병을 무료로 얻으십시오."}},
[333] = {"할란의 새 공급품", {"대운하 의류점으로 가서 레마 슈나이더에게 할란 바글리가 보내는 옷감 주문서를 전해줘야 합니다."}},
[334] = {"투르만의 준비물", {"스톰윈드 마법사 지구에 있는 라슨의 옷가게로 가서 투르만 슈나이더에게 바느질 도구를 주어야 합니다."}},
[335] = {"귀족을 위한 술", {"검은발톱 자데스가 다크샤이어에서 틸로아의 눈물과 저습지에서 사향쥐 뿌리를 가져다 달라고 부탁했습니다."}},
[336] = {"귀족을 위한 술", {"왕국 민원실에 있는 보울즈 K. 위쇼크 경에게 검은발톱 스타우트 맥주를 주어야 합니다."}},
[337] = {"오래된 역사책", {"스톰윈드 도서관에 스톰윈드의 역사 책을 돌려줘야 합니다."}},
[338] = {"가시덤불 골짜기의 푸른 언덕", {"가시덤불 골짜기의 푸른 언덕 원고의 잃어버린 페이지들을 모아야 합니다. 네 개의 장이 모두 완성되면 바닐 스톤팟에게 가져가십시오."}},
[339] = {"제 1 장", {"바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 1장을 완성할 수 있도록 1, 4, 6, 8 쪽을 가져가야 합니다."}},
[340] = {"제 2 장", {"바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 2장을 완성할 수 있도록 10, 11, 14, 16 쪽을 가져가야 합니다."}},
[341] = {"제 3 장", {"바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 3장을 완성할 수 있도록 18, 20, 21, 24 쪽을 가져가야 합니다."}},
[342] = {"제 4 장", {"바닐 스톤팟이 네싱워리의 소설 가시덤불 골짜기의 푸른 언덕의 4장을 완성할 수 있도록 25, 26, 27 쪽을 가져가야 합니다."}},
[343] = {"불굴의 의지에 대한 연설", {"스톰윈드 왕궁에 있는 왕실 도서관으로 가서 밀턴 시프와 대화해야 합니다. 그는 수사 크리스토프가 연설에 필요로 하는 야금술에 대한 책을 찾아 줄 수 있습니다."}},
[344] = {"수사 팩스턴", {"노스샤이어 수도원에 있는 수사 팩스턴과 대화해야 합니다."}},
[345] = {"잉크 공급", {"레이크샤이어에 있는 현장감독 오슬로우와 대화하여 레스밴 철광석을 달라고 부탁해야 합니다."}},
[346] = {"수사 크리스포트에게로", {"대성당 광장에 있는 수사 크리스토프에게 돌아가서 '철강의 중요성'을 전달해야 합니다."}},
