[434] = {"공격!", {"그레골 라스코발 경과 소리없는검객 마르존이 대화를 나눌때까지 정원에서 기다려야 합니다. 그후에 모두 처치한 후 스톰윈드에 있는 엘링 트리아스에게 돌아가야 합니다."}},
[435] = {"엘런드 경호", {"레인 요릭이 있는 곳까지 늑대들을 물리치고 엘런드를 경호해야 합니다."}},
[436] = {"아이언밴드의 발굴 현장", {"탐험가 펠휴와 대화하십시오."}},
[437] = {"죽음의 농장", {"죽음의 농장에서 썩은가죽 놀들을 처치하십시오. 나이트래쉬가 나타나면 그녀를 처치하십시오.","","공동묘지에 있는 고위집행관 하드렉에게 나이트래쉬의 정수를 가져가야 합니다."}},
[438] = {"오래된 나루터", {"오래된 나루터로 가서 그곳에 스컬지가 주둔한 이유를 찾아내야 합니다."}},
