[445] = {"은빛소나무 숲으로의 배달", {"은빛소나무 숲에 있는 연금술사 렌퍼럴에게 요한의 연구 결과를 전달해야 합니다."}},
[446] = {"까마귀발톱 쑤울", {"은빛소나무 숲 공동묘지에 있는 연금술사 렌퍼럴에게 베소르의 두루마리를 가져가야 합니다."}},
[447] = {"죽음의 비법", {"불곰 심장 6개와 땅거미 점액 6개를 모아 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다."}},
