[456] = {"자연의 균형", {"새끼 흑호 7마리와 새끼 엉겅퀴멧돼지 4마리를 처치한 다음 관리인 일사레인에게 돌아가십시오."}},
[457] = {"자연의 균형", {"관리인 일사레인이 병든 흑호 7마리와 엉겅퀴멧돼지 7마리를 처치해 달라고 부탁했습니다."}},
