[520] = {"의지의 왕관", {"무그톨을 처치하고 그 증거로 그의 머리카락과 의지의 왕관을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다."}},
[521] = {"의지의 왕관", {"언더시티에 있는 샬린드라에게 의지의 왕관을 가져가야 합니다."}},
[524] = {"죽음의 비약", {"오염된 맥주통을 사로잡힌 농부들이 있는 방의 양탄자 위에 가져다 놓아야 합니다."}},
[525] = {"깊어지는 의문", {"사우스쇼어에 있는 집정관 말레브에게 해독된 편지를 가져가야 합니다."}},
[527] = {"힐스브래드 전투", {"힐스브래드 농노 6명, 힐스브래드 농부 6명, 그리고 농부 레이와 농부 게츠를 처치한 다음 타렌 밀농장에 있는 다살리아에게 보고해야 합니다."}},
[528] = {"힐스브래드 전투", {"힐스브래드 소작농 15명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}},
[529] = {"힐스브래드 전투", {"대장장이 베링턴과 힐스브래드 견습대장장이 4명을 처치해야 합니다.","","철괴 상자를 찾은 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오."}},
[530] = {"랠리의 복수", {"발드레드 모레이를 처치해야 합니다.","","그 증거로 언더시티에 있는 랠리 앤드리언에게 발드레드의 장갑을 가져가야 합니다."}},
[531] = {"바이린의 복수", {"순찰자의 오두막에 있는 바이린 스위프트윈드에게 늙은곰 수티의 머리를 가져가야 합니다."}},
[532] = {"힐스브래드 전투", {"집정관 번사이드와 힐스브래드 원로 5명을 처치해야 합니다. 힐스브래드 선언문을 파괴하고 힐스브래드 마을의 기록부를 빼내 와야 합니다. 그런 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오."}},
[533] = {"침투", {"타렌 밀농장에 있는 크루스크를 위해 골디르가 어디에 있는지 정보를 찾아야 합니다."}},
[535] = {"발릭", {"비밀결사대 야영지에 있는 발릭에게 사우스쇼어의 스타우트 맥주 한 잔을 가져가야 합니다."}},
[536] = {"해안의 위협", {"사우스쇼어에 있는 부관 파렌 오리넬이 너덜지느러미멀록 바다사냥꾼 10마리와 너덜지느러미멀록 점쟁이 10마리를 처치해달라고 부탁했습니다."}},
[537] = {"어둠의 의회", {"아르거스 재림회 어둠마법사 4명을 처치해야 합니다.","","그리고 나가즈를 처치한 증거로 그의 머리카락을 사우스쇼어에 있는 집정관 헨리 말레브에게 가야 합니다."}},
[538] = {"사우스쇼어", {"사우스쇼어에 있는 현자 딥스와 대화해야 합니다."}},
[539] = {"힐스브래드 전투", {"현장감독 본즈와 힐스브래드 광부 10명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}},
[540] = {"지식 보존", {"되찾은 학술서 5권과 그리렉의 팔이 들어 있는 낡은 가죽 책을 사우스쇼어에 있는 현자 딥스에게 가져가야 합니다."}},
[541] = {"힐스브래드 전투", {"던 가록으로 가서 던 가록 산악경비대 10명, 던 가록 소총병 8명, 던 가록 사제 4명과 부대장 아이언힐을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}},
[542] = {"밀턴에게 돌아가기", {"스톰윈드에 있는 밀턴 시프에게 알터랙의 학술서를 가져가야 합니다."}},
[543] = {"페레놀드 티아라", {"스톰윈드에 있는 레밍턴 리지웰에게 페레놀드 티아라를 가져가야 합니다."}},
[544] = {"감옥 습격", {"배반자들을 찾아내 유물을 되찾은 다음에 돌아가야 합니다."}},
[545] = {"달라란 순찰", {"달라란 소환사 6명과 노예 바위 정령 8마리를 처치한 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다."}},
[546] = {"죽음의 전리품", {"타렌 밀농장에 있는 죽음경비병 삼사가 힐스브래드 주민의 해골 30개를 가져다 달라고 부탁했습니다."}},
[547] = {"험버트의 검", {"던 가록에서 죽음경비병 험버트의 검을 되찾아 타렌 밀농장으로 돌아와 험버트에게 검을 돌려줘야 합니다."}},
[549] = {"비밀결사대원 현상수배", {"비밀결사대 도적 10명과 비밀결사대 경비병 10명을 처치해야 합니다. 그런 다음 타렌 밀농장에 있는 고위집행관 다살리아에게 돌아가 보상금을 받으십시오."}},
[550] = {"힐스브래드 전투", {"언더시티에 있는 바리마트라스에게 다살리아의 봉인된 추천서를 가져가야 합니다."}},
[551] = {"마법의 양피지", {"사우스쇼어에 있는 현자 딥스에게 마법의 양피지를 가져가야 합니다."}},
[552] = {"헬쿨라의 복수", {"설인에게서 헬쿨라의 마법봉을 되찾아 타렌 밀농장에 있는 수련사 사이반드에게 가져가야 합니다."}},
[553] = {"헬쿨라의 복수", {"헬쿨라의 마법봉에 아젤의 불꽃, 베라즈의 불꽃, 우젤의 불꽃의 마력을 불어넣어야 합니다.","","힘을 불어넣은 마법봉을 사우스쇼어에 있는 헬쿨라의 무덤으로 가져가야 합니다."}},
[554] = {"스톰파이크의 판독", {"아이언포지에 있는 발굴조사단장 스톰파이크에게 마법의 양피지를 가져가야 합니다."}},
[555] = {"독특한 거북이 비스크", {"사우스쇼어에 있는 주방장 예센에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다."}},
[556] = {"징표의 돌", {"타렌 밀농장에 있는 관리인 벨바릴에게 닳아해진 징표의 돌 10개를 가져가야 합니다."}},
[557] = {"결속의 팔보호구", {"타렌 밀농장에 있는 관리인 벨바릴에게 대지 결속의 팔보호구 4개를 가져가야 합니다."}},
[559] = {"파렌의 증거물", {"사우스쇼어에 있는 부관 파렌 오리넬에게 서부 해안에서 멀록을 처치하고 멀록 머리 10개를 모아야 합니다."}},
[560] = {"파렌의 증거물", {"사우스쇼어에 있는 치안대장 레드패스에게 멀록 머리가 든 자루를 전달해야 합니다."}},
[561] = {"파렌의 증거물", {"사우스쇼어에 있는 부관 파렌 오리넬과 대화해야 합니다."}},
[562] = {"아, 스톰윈드!", {"사우스쇼어에 있는 부관 파렌 오리넬을 위해 비수가시일족 바다사냥꾼 10마리와 비수가시일족 세이렌 10마리를 처치해야 합니다."}},
