[595] = {"붉은해적단", {"일등항해사 크래즈가 무법항 북쪽의 작은 만을 조사해 달라고 부탁했습니다."}},
[596] = {"피묻은 뼈목걸이", {"그롬골 주둔지에 있는 킨윌레이에게 피묻은 뼈목걸이 25개를 가져가야 합니다."}},
