[878] = {"부족 간의 전쟁", {"뾰족털일족의 풍수사 6명, 가시마술사 12명, 흙점쟁이 12명을 처치해야 합니다. 임무를 완수한 후 불모의 땅, 타우라조 야영지에 있는 뻐드렁니에게 돌아가십시오."}},
[879] = {"내부의 배반자", {"나크와 쿠즈, 로크를 처단하여 그들의 해골을 불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 가져가야 합니다."}},
[880] = {"변화된 생물", {"크로스로드에 있는 통가 룬토템에게 변형된 무쇠턱거북 등껍질 8개를 가져다주어야 합니다."}},
[881] = {"에체야키", {"크로스로드에 있는 셀그라 다크쏜에게 에체야키의 통가죽을 가져가야 합니다."}},
[882] = {"이샤무헤일", {"타우라조 야영지에 있는 조른 스카이시어에게 이샤무헤일의 송곳니를 가져가야 합니다."}},
[883] = {"라코타마니", {"타우라조 야영지에 있는 조른 스카이시어에게 라코타마니의 발굽을 가져가야 합니다."}},
[884] = {"오와탄카", {"타우라조 야영지에 있는 조른 스카이시어에게 오와탄카의 꼬리가시를 가져가야 합니다."}},
[885] = {"워시트 포우니", {"타우라조 야영지에 있는 조른 스카이시어에게 워시트 포우니의 깃털을 가져가야 합니다."}},
[886] = {"불모의 땅 오아시스", {"크로스로드에 있는 통가 룬토템과 대화해야 합니다."}},
[887] = {"남쪽바다 해적단", {"톱니항에 있는 가즈로를 위해 남쪽바다 해적단 약탈자 12명과 남쪽바다 해적단 포병 6명을 처치해야 합니다."}},
[888] = {"도난당한 전리품", {"톱니항에 있는 가즈로를 위해 장화가 든 뱃짐과 망원경 렌즈를 찾아 와야 합니다."}},
[889] = {"바람의 정기", nil},
[890] = {"사라진 뱃짐", {"부두주임 디지위그에게 가즈로의 장부를 가져가야 합니다."}},
[891] = {"전초기지의 대포", {"톱니항에 있는 선장 탈로타스 브라이트썬이 테라모어 휘장 10개를 모으고 경비대장 페어마운트, 포병 훼산, 포병 스미스를 처치해 달라고 부탁했습니다."}},
[892] = {"사라진 뱃짐", {"톱니항에 있는 가즈로에게 가즈로의 장부를 돌려주어야 합니다."}},
[893] = {"최고의 무기", {"불모의 땅, 타우라조 야영지에 있는 테터낵 스틸포지에게 서슬갈기일족의 기습용 단검, 불타는 마법봉, 그리고 전투용 방패를 가져가야 합니다."}},
[894] = {"사모플랜지", {"투자개발회사 연구 시설의 제어장치로 접근해야 합니다."}},
[895] = {"롱쇼어 남작 현상수배", {"롱쇼어 남작을 처치하고 그 증거로 그의 머리카락을 톱니항에 있는 가즈로에게 가져다주어야 합니다."}},
[896] = {"광부의 행운", {"톱니항에 있는 부두주임 디지위그가 투자개발회사 감독이나 투자개발회사 집행자로부터 고양이눈 에메랄드를 가져다 달라고 부탁했습니다."}},
[897] = {"여왕 실리시드", {"조른 스카이시어에게 여왕 실리시드의 머리를 가져다주어야 합니다."}},
[898] = {"요새 탈출", {"길사레즈 파이어바우를 톱니항에 있는 브라이트썬 선장에게 데려가야 합니다."}},
[899] = {"타오르는 증오", {"크로스로드에 있는 만크릭에게 뾰족털 가시멧돼지 어금니 60개를 가져가야 합니다."}},
[900] = {"사모플랜지", {"연료 제어 밸브, 압력 조절 밸브, 주제어 밸브를 잠근 다음 제어장치로 돌아가십시오."}},
[901] = {"사모플랜지", {"땜장이 스니글즈에게서 제어장치 열쇠를 구해야 합니다."}},
[902] = {"사모플랜지", {"톱니항에 있는 스퍼터밸브에게 사모플랜지를 가져가야 합니다."}},
[903] = {"불모의 땅의 굶주린 사자", {"불모의 땅의 굶주린 사바나 사자에게서 굶주린 사자의 발톱 7개를 모아 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오."}},
[905] = {"성난 갈퀴발톱 열대초원랩터", {"열대초원랩터를 처치하고 그들의 깃털을 모아야 합니다. 이 깃털을 열대초원랩터 둥지 3개에 사용한 다음 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오."}},
[906] = {"내부의 배반자", {"불모의 땅, 크로스로드에 있는 톨크에게 로크의 해골을 가져가야 합니다."}},
[907] = {"분노한 천둥도마뱀", {"천둥도마뱀 피 3개를 모아 타우라조 야영지에 있는 조른 스카이시어에게 가져다주어야 합니다."}},
[913] = {"천둥매의 울음 소리", {"천둥매를 찾아 처치하고 천둥매 날개를 타우라조 야영지에 있는 조른 스카이시어에게 가져가야 합니다."}},
[914] = {"송곳니의 드루이드 우두머리", {"코브란, 아나콘드라, 피타스, 서펜티스의 보석을 모아 썬더 블러프에 있는 나라 와일드메인에게 돌아가야 합니다."}},
[916] = {"나무그물거미의 독", {"알드랏실에 있는 길스할란 윈드워커에게 나무그물거미의 독주머니 10개를 가져가야 합니다."}},
[917] = {"나무그물거미알", {"알드랏실에 있는 길스할란에게 나무그물거미알을 가져가야 합니다."}},
[918] = {"나무괴물 씨앗", {"알아메스 호수에 있는데날란에게 나무괴물 씨앗 8개를 가져가야 합니다."}},
[919] = {"나무괴물 씨눈", {"알아메스 호수에 있는 데날란에게 나무괴물 씨눈 12개를 가져가야 합니다."}},
[920] = {"테나론의 부름", {"그늘 협곡, 알드랏실 꼭대기에 있는 테나론 스톰그립과 대화하십시오."}},
[921] = {"대지의 왕관", {"수정 약병에 물을 채워서 알드랏실 꼭대기에 있는 테나론 스톰그립에게 돌아오십시오."}},
[922] = {"레엘리안 그린스파이어", {"다르나서스에 있는 레엘리안 그린스파이어에게 나무괴물 씨앗을 가져가야 합니다."}},
[923] = {"종양", {"다르나서스에 있는 레엘리안 그린스파이어에게 이끼 낀 종양 5개를 가져가야 합니다."}},
[924] = {"악마의 씨앗", {"우선 혼란의 마법석을 손에 넣으십시오. 마법석의 힘이 다하기 전에 불의 제단에 가져다 놓은 후 아크젤로스에게 돌아가십시오."}},
