[928] = {"대지의 왕관", {"돌라나르에 있는 코리드라스 문레이지에게 반쯤 찬 유리병을 가져가십시오."}},
[929] = {"대지의 왕관", {"비취 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다."}},
[930] = {"빛나는 과일", {"알아메스 호수에 있는 데날란에게 빛나는 과일을 가져가야 합니다."}},
[931] = {"희미하게 빛나는 잎", {"알아메스 호수에 있는 데날란에게 희미하게 빛나는 잎을 가져가야 합니다."}},
[932] = {"뒤틀린 증오", {"제왕 멜레나스를 처치한 다음 돌라나르에 있는 탈론카이 스위프트루트에게 멜레나스의 머리띠를 가져가야 합니다."}},
[933] = {"대지의 왕관", {"전기석 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다."}},
[935] = {"대지의 왕관", {"다르나서스에 있는 대드루이드 판드랄 스테그헬름에게 가득 찬 유리병을 가져가야 합니다."}},
[937] = {"마법의 터", {"붉은깃털일족 허리띠 6개를 구해 신탁의 숲에 있는 파수꾼 아리니아 클라우드브레이크에게 가져가야 합니다."}},
[938] = {"미스트", {"신탁의 나무 근처의 달샘에 있는 파수꾼 아리니아 클라우드브레이크에게 미스트를 데려가야 합니다."}},
[940] = {"텔드랏실", {"다르나서스에 있는 대드루이드 판드랄 스태그헬름에게 글씨가 새겨진 나무껍질을 전달해야 합니다."}},
[941] = {"오염된 심장 재배", {"데날란의 화분에 오염된 심장을 심어야 합니다."}},
[942] = {"정신 없는 발굴조사단장", {"메네실 항구에 있는 고고학자 플라곤구트에게 신비로운 화석을 가져가야 합니다."}},
[943] = {"정신 없는 발굴조사단장", {"메네실 항구에 있는 고고학자 플라곤구트가 렐루의 돌과 플라곤구트의 화석을 가져다 달라고 부탁했습니다."}},
[944] = {"지배자의 무덤", {"정보를 수집한 다음 수정점의 유리병을 사용하여 수정점 그릇을 만드십시오. 만들어진 그릇을 사용하여 오누와 대화하십시오."}},
[945] = {"테리루네의 탈출", {"테리루네의 탈출을 도운 다음 아에시나의 제단에 있는 테리실에게 그녀가 무사하다는 사실을 알려야 합니다."}},
[947] = {"동굴 버섯", {"아우버다인에 있는 바리스라스 문셰이드에게 껄껄이그물버섯 5개와 알광대버섯 1개를 가져가야 합니다."}},
[948] = {"오누", {"고대정령의 숲에서 오누와 대화하십시오."}},
