[951] = {"마시스트라의 유물", {"고대정령의 숲에 있는 오누에게 마시스트라 유물 6개를 가져가야 합니다."}},
[952] = {"고대정령의 숲", {"어둠의 해안, 고대정령의 숲에 있는 오누에게 판드랄의 전갈을 전해야 합니다."}},
[953] = {"아메스아란의 멸망", {"멸망한 아메스아란의 역사가 기록되어 있는 서판의 내용을 알아낸 다음 어둠의 해안에 있는 파수꾼 티샤 문블레이드에게 돌아가십시오."}},
[954] = {"바샬아란", {"바샬아란의 폐허에 감도는 이상한 푸른 기운의 근원을 찾아야 합니다."}},
