[956] = {"바샬아란", {"고대 월장석 봉인을 찾아 바샬아란에 있는 아스테리온에게 가져가야 합니다."}},
[957] = {"바샬아란", {"아메스아란에 있는 고대의 불꽃으로 고대 월장석 봉인을 파괴한 다음 바샬아란에 있는 아스테리온에게 돌아가십시오."}},
[958] = {"명가의 도구", {"아우버다인에 있는 툰드리스 윈드위버를 위해 명가의 유물 7개를 찾아 와야 합니다."}},
[959] = {"99년 묵은 와인", {"톱니항에 있는 기중기 기사 비글퍼즈가 통곡의 동굴에 숨어 있는 광기의 매글리시에게서 99년 숙성된 포트 와인을 되찾아 달라고 부탁했습니다."}},
[962] = {"불뱀꽃", {"썬더 블러프에 있는 연금술사 자마가 불뱀꽃 10개를 모아 달라고 부탁했습니다."}},
[963] = {"영원한 사랑", {"아나야 돈러너의 영혼을 자유롭게 한 다음 그녀의 펜던트를 아우버다인에 있는 셀렐리안 화이트클로에게 가져가야 합니다."}},
