[976] = {"아우버다인으로의 보급품", {"피로가 안전하게 잿빛 골짜기를 통과하도록 경호한 뒤 마에스트라 주둔지에 있는 수호자 델그렌과 대화하십시오."}},
[978] = {"달빛의 올빼미야수", {"여명의 설원에서 달빛 깃든 깃털을 10개 모아서 루테란 마을의 에릴라스 엠버스카이에게 가져와야 합니다."}},
[980] = {"새로운 온천", {"여명의 설원으로 가서 도노바 스노우덴과 대화하십시오."}},
[982] = {"깊고 푸른 바다", {"아우버다인에 있는 골볼트 스틸핸드에게 은빛 새벽호의 금고와 안개 장막호의 금고를 가져가야 합니다. 모두 마을의 북쪽에 있는 난파선에서 찾을 수 있을 것입니다."}},
[983] = {"버즈박스 827", {"집게다리 6개를 모아 버즈박스 827에 넣어야 합니다."}},
[984] = {"거대한 위협", {"어둠의 해안에서 오염된 펄볼그 야영지를 찾은 다음 아우버다인에 있는 테렌디스에게 돌아가십시오."}},
[985] = {"거대한 위협", {"검은나무일족 길잡이 8마리와 풍수사 5마리를 처치한 다음 아우버다인에 있는 테렌디스에게 돌아가십시오."}},
[986] = {"사라진 주인", {"고급 달표범 모피 5필을 찾아 아우버다인에 있는 테렌디스에게 가져가야 합니다."}},
[990] = {"잿빛 골짜기로의 여정", {"잿빛 골짜기에 있는 레이네 울프러너를 찾아가야 합니다."}},
[991] = {"레이네의 정화", {"잿빛 골짜기에서 테로니스를 찾아야 합니다."}},
[992] = {"가젯잔 수자원 측량", {"슬픈모래 감시탑의 물 웅덩이 부근에서 추출 전의 탐사장치를 사용하십시오. 다 채웠으면 가젯잔에 있는 선임측량사 피즐도저에게 추출한 탐사장치를 가져가야 합니다."}},
[993] = {"사라진 주인", {"어둠의 해안에 있는 볼코르를 찾아서 마법 달표범 망토를 주어야 합니다."}},
[994] = {"무력 탈출", {"길에 이를 때까지 볼코르를 보호한 다음 아우버다인에 있는 테렌디스와 대화하십시오."}},
[995] = {"은밀한 탈출", {"펄볼그 동굴을 탈출한 다음 아우버다인에 있는 테렌디스를 만나십시오."}},
[997] = {"데날란의 흙", {"알아메스 호수에 있는 데날란에게 귀한 흙을 가져가야 합니다."}},
[1001] = {"버즈박스 411", {"버즈박스 411 근처 깊은 바다에 있는 어둠의해안 트레샤돈에게서 트레샤돈의 눈 3개를 모아야 합니다."}},
[1002] = {"버즈박스 323", {"달표범 송곳니 6개를 모아 버즈박스 323에 넣어야 합니다."}},
[1003] = {"버즈박스 525", {"아우버다인 남쪽에 있는 엉겅퀴불곰에게서 불곰 가죽 4개를 모아 버즈박스 525에 집어넣어야 합니다."}},
[1004] = {"새로운 미개척지", {"썬더 블러프, 장로의 봉우리에 있는 대드루이드 하뮬 룬토템을 찾아가 세나리온 의회의 칼림도어 개척 지원자 모집에 대한 얘기를 나눠야 합니다."}},
[1007] = {"고대 조각상", {"조람 해안 근처에서 야영하고 있는 탈렌에게 고대 조각상을 가져가야 합니다."}},
[1008] = {"조람 해안", {"아스트라나르에 있는 신드렐 스위프트파이어에게 성난지느러미일족의 머리 20개를 가져가야 합니다."}},
[1009] = {"루젤", {"조람 해안 근처에 있는 탈렌에게 조람의 반지를 가져가야 합니다."}},
[1010] = {"배스랜초", {"잿빛 골짜기에 있는 오렌딜 브로드리프에게 배스랜초 5개를 가져가야 합니다."}},
[1011] = {"포세이큰의 역병", {"숲의 노래에 있는 케이네스 스틸윈드에게 역병 견본 하나를 가져가야 합니다."}},
[1012] = {"미쳐버린 드루이드", {"드루이드 지도자인 타닐 다크우드, 우실 문콜, 마보리스 클라우즈브레이크를 처치한 다음 숲의 노래에 있는 케이네스 스틸윈드에게 돌아가십시오."}},
[1013] = {"우르의 책", {"언더시티의 연금술 실험실에 있는 관리인 벨두거에게 우르의 책을 가져가야 합니다."}},
[1014] = {"아루갈의 최후", {"아루갈을 처치하고 그 증거로 그의 머리카락을 공동묘지에 있는 달라 던위버에게 가져가야 합니다."}},
[1015] = {"새로운 미개척지", {"다르나서스의 세나리온 자치령에 있는 대드루이드 판드랄 스테그헬름을 찾아가 세나리온 의회의 칼림도어 미개척지 탐험 지원자 모집에 대한 얘기를 나눠야 합니다."}},
[1016] = {"정령의 족쇄", {"온전한 정령의 족쇄 5개를 모아서 예언의 두루마리를 사용한 후, 실바람 산장에 있는 파수꾼 벨레네 스타스트라이크에게 예언된 두루마리를 가져가야 합니다."}},
[1017] = {"물의 정령 배후의 마법사", {"사릴루스 파울본을 처치하고 그 증거로 그의 머리카락을 실바람 산장에 있는 파수꾼 벨레네 스타스트라이크에게 가져가야 합니다."}},
[1020] = {"오렌딜의 치료제", {"아스트라나르에 있는 펠투러스 화이트문에게 오렌딜의 치료제를 가져가야 합니다."}},
[1021] = {"사악한 사티로스와 위험에 처한 드리아드", {"잿빛 골짜기 북동쪽에 있는 사비안에서 아닐리아를 찾아야 합니다."}},
[1022] = {"울부짖는 골짜기", {"울부짖는 골짜기로 가서 멜탄드리스의 마법책을 찾아 읽어 본 다음 아에시나의 제단에 있는 파수꾼 멜리리아 프로스트섀도에게 돌아가십시오."}},
[1023] = {"레이네의 정화", {"빛나는 보석을 찾아 테로니스의 일지와 함께 아스트라나르에 있는 레이네 울프러너에게 가져가야 합니다."}},
[1024] = {"레이네의 정화", {"북동쪽에 있는 달샘에서 셸드린을 찾아야 합니다."}},
[1025] = {"공격적 방어", {"썩은나무일족 보초 1마리, 썩은나무일족 펄볼그 2마리, 썩은나무일족 토템술사 10마리 및 썩은나무일족 전사 12마리를 처치한 다음 아스트라나르에 있는 레이네 울프러너에게 돌아가십시오."}},
[1026] = {"레이네의 정화", {"나무 열쇠와 다르톨의 변신마법봉의 조각을 찾아 달샘에 있는 셸드린에게 돌아가십시오."}},
[1027] = {"레이네의 정화", {"다르톨의 마법봉을 만들기 위한 마지막 조각을 찾아 달샘에 있는 셸드린에게 돌아가십시오."}},
[1028] = {"레이네의 정화", {"숨겨진 제단을 찾아 다르톨의 마법봉에 다시 마력을 불어 넣어야 합니다."}},
[1029] = {"레이네의 정화", {"아스트라나르에 있는 레이네 울프러너에게 돌아가십시오."}},
[1031] = {"세나리우스의 가지", {"겔타리스를 처치하고 아에시나의 제단에 있는 일리야나에게 세나리우스의 가지를 돌려줘야 합니다."}},
[1032] = {"사티로스 처치", {"아에시나의 제단에 있는 일리야나에게 사티로스의 뿔 16개를 가져다주어야 합니다."}},
[1033] = {"엘룬의 눈물", {"아스트라나르에 있는 펠투러스에게 엘룬의 눈물을 가져가야 합니다."}},
[1034] = {"별가루의 폐허", {"아스트라나르에 있는 펠투러스에게 별가루 5줌을 가져가야 합니다."}},
[1035] = {"유성 호수", {"그늘덤불 나무현자에게서 유성 월장석을 빼앗아서 아스트라나르에 있는 펠투러스에게 가져가야 합니다."}},
[1037] = {"벨린데 스타송", {"다르나서스의 전사의 정원에 있는 신텔 블레이드위버와 대화하십시오."}},
[1041] = {"행상길", {"다크샤이어에 있는 서기관 달트리와 대화하십시오."}},
[1043] = {"엘룬의 낫", {"엘룬의 낫의 흔적을 찾은 다음 다크샤이어에 있는 조나단 카레빈에게 돌아가야 합니다."}},
[1048] = {"붉은십자군 수도원으로", {"종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 돌아가 보고해야 합니다."}},
[1049] = {"타락의 개요", {"티리스팔 숲의 붉은십자군 수도원에서 타락의 개요를 찾아 썬더 블러프에 있는 현자 트루스시커에게 가져가야 합니다."}},
[1050] = {"티탄 신화", {"수도원에서 티탄 신화라는 책을 찾아 아이언포지에 있는 사서 메이 페일더스트에게 가져가야 합니다."}},
[1051] = {"보렐의 복수", {"타렌 밀농장에 있는 모니카 센구츠에게 보렐의 결혼반지를 가져가야 합니다."}},
[1052] = {"붉은십자군의 길", {"사우스쇼어에 있는 경건한 신자 랄레이에게 수사 안톤의 추천서를 가져가야 합니다."}},
[1053] = {"빛의 이름으로!", {"종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 사우스쇼어에 있는 경건한 신자 랄레이에게 돌아가 보고하십시오."}},
[1054] = {"위협 제거", {"아스트라나르에 있는 레이네 울프러너에게 달 블러드클로의 해골을 가져가야 합니다."}},
[1055] = {"레이네의 정화", {"<name>샘에 있는 셸드린에게 돌아가십시오."}},
[1056] = {"돌발톱 봉우리로의 여정", {"돌발톱 봉우리에 있는 수호자 알바고름을 찾아가십시오."}},
[1057] = {"잿더미 계곡 복원", {"돌발톱 봉우리에 있는 수호자 알바고름이 혈폭풍하피 6마리, 혈폭풍일족 복병 6마리, 혈폭풍일족 암살자 6마리, 그리고 혈폭풍일족 약탈자 6마리를 처치해 달라고 부탁했습니다."}},
[1058] = {"진질의 숲의 마법", {"말라카진에 있는 의술사 진질이 돌발톱 수액 5개, 황혼의 수염 5개, 순록의 눈 30개와 마룡 비늘 1개를 가져다 달라고 부탁했습니다."}},
[1059] = {"잿더미 계곡 복원", {"버섯구름 봉우리와 페랄라스의 경계에 있는 팔핀델 웨이워더를 찾아가야 합니다."}},
[1060] = {"진질에게 보내는 편지", {"돌발톱 산맥의 동굴에서 야영을 하는 진질에게 달소크의 편지를 전달하십시오."}},
[1061] = {"돌발톱 산맥의 정령", {"돌발톱 산맥에 있는 시리스 스톤브레이크와 대화하십시오."}},
[1062] = {"고블린 침략자", {"투자개발회사 나무꾼 15명을 처치한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오."}},
[1063] = {"원로 마가타", {"썬더 블러프에 있는 마가타와 대화하십시오."}},
[1064] = {"포세이큰의 원조", {"썬더 블러프의 예언의 웅덩이에 있는 연금술사 자마와 대화해야 합니다."}},
[1065] = {"타렌 밀농장으로의 모험", {"타렌 밀농장에 있는 연금술사 라이던에게 자마의 쪽지를 가져가야 합니다."}},
[1066] = {"순결한 피", {"타렌 밀농장에 있는 연금술사 라이던에게 순결한 피가 든 유리병 5병을 가져가야 합니다."}},
[1067] = {"썬더 블러프로의 귀환", {"썬더 블러프에 있는 연금술사 자마에게 라이던의 독약을 가져가야 합니다."}},
[1068] = {"벌목기", {"벌목기 XT:4와 XT:9를 파괴한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오."}},
[1069] = {"동굴이끼거미알", {"톱니항에 있는 메보크 미지릭스에게 동굴이끼거미알 15개를 가져가야 합니다."}},
[1070] = {"돌발톱 산맥에서의 임무", {"돌발톱 산맥에 있는 칼바람 바위산 입구에 계곡이 내려다보이는 곳에 캘라 섀도스피어를 찾아야 합니다."}},
[1071] = {"노움의 부탁", {"투자개발회사 나무꾼 10명 및 투자개발회사 벌채꾼 10명을 처치하고 돌발톱 산맥에 있는 각심 러스트피즐에게 돌아가십시오."}},
[1072] = {"오랜 동료", {"아이언포지에 있는 로막 기어스트립과 대화하십시오."}},
[1073] = {"어리석음 + 화학 물질 = 재미", {"아이언포지에 있는 로막 기어스트립에게 최하급 마나 물약 4개와 최하급 인내의 비약 2개를 가져가야 합니다."}},
