[2280] = {"백금 원반", {"썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다."}},
[2281] = {"붉은마루 집결", {"붉은마루 산맥의 레이크샤이어로 가서 루시우스와 대화해야 합니다."}},
[2282] = {"앨더의 제재소", {"루시우스의 금고를 열고 <name>의 징표를 회수한 다음 레이크샤이어에 있는 루시우스에게 가져가야 합니다."}},
[2283] = {"목걸이 회수", {"울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다."}},
[2284] = {"목걸이 회수 - 2차 시도", {"울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다."}},
[2298] = {"왕의 철저한 수색", {"스톰윈드로 가서 칼잡이 렌직을 찾아야 합니다."}},
[2299] = {"훌프단에게로!", {"아이언포지로 가서 훌프단 블랙비어드와 대화하십시오."}},
[2318] = {"일지 번역", {"성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다."}},
[2338] = {"일지 번역", {"자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다."}},
[2339] = {"보석과 마력원천 찾기", {"울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.","","일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다.","","토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다.","","사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다.","","마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다."}},
[2340] = {"보석 전달", {"오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다."}},
[2341] = {"목걸이 회수 - 3차 시도", {"카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오."}},
[2342] = {"보물 되찾기", {"울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다."}},
[2359] = {"클라벤의 탑", {"데피아즈단 탑 열쇠를 훔쳐 데피아즈단 탑으로 숨어 들어간 후, 그늘숲 궤짝에 무엇이 들어 있는지 밝혀 내야 합니다. 알아낸 모든 정보를 가지고 스톰윈드에 있는 마티아스 쇼에게 돌아가야 합니다. 켈넌의 보고서을 읽고 탑에 대한 정보를 얻으십시오."}},
[2360] = {"마티아스와 데피아즈단", {"서부 몰락지대로 가서 첩보원 켈넌을 찾아 보고를 받아야 합니다."}},
[2361] = {"목걸이 복원", nil},
[2378] = {"검은손 도적단을 찾아서", {"오그리마로 가서 어둠의 틈에 있는 셴툴과 대화해야 합니다."}},
[2379] = {"잔도잔", {"어둠의 틈에 있는 잔도잔과 대화하십시오."}},
[2380] = {"오그리마로!", {"오그리마의 어둠의 틈에 있는 셴툴과 대화하십시오."}},
[2381] = {"약탈자 약탈하기", {"톱니항에 있는 비운의 레닉스에게 남쪽바다해적단 보물을 가져가야 합니다. 레닉스의 기계장치에서 E.C.A.C.와 도둑 도구를 얻는 것도 잊지 마십시오. 임무를 완수하려면 이 두 가지가 모두 필요합니다.","","유별나게 공격적인 앵무새에게 맞서게 되면 E.C.A.C.를 사용하십시오!"}},
[2382] = {"톱니항의 레닉스", {"톱니항으로 가서 비운의 레닉스와 대화하십시오."}},
[2383] = {"간결한 양피지", {"간결한 양피지를 읽어보고 프랑에게 양피지를 가져가야 합니다."}},
[2398] = {"길 잃은 드워프", {"울다만에서 밸로그를 찾아야 합니다."}},
[2399] = {"싹튼 잎", nil},
[2418] = {"마법석", {"황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다."}},
[2438] = {"에메랄드의 꿈 흡입기", {"돌라나르에 있는 탈론카이 스위프트루트에게 에메랄드의 꿈 흡입기를 가져다주어야 합니다."}},
[2439] = {"백금 원반", {"아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다."}},
[2440] = {"백금 원반", {"썬더 블러프에 있는 베나 윈터후프에게 사례 보증 서류를 가져가야 합니다."}},
[2458] = {"잠입", {"진흙 늪 북쪽에 있는 투자개발회사 탑으로 가서 검은손 도적단의 비밀 요원인 감독관 피줄과 접촉해야 합니다.","","탑이 보이면 섬광탄포를 사용해 감독관 피줄에게 당신이 도착했음을 알리십시오. 섬광탄은 2번 발사해야 하며, 그 후 감독관 피줄에게 다가가 검은손 도적단 /경례를 해야 합니다.","","피줄은 자기가 모르는 자는 무조건 처치하려 들기 때문에 정확한 순서대로 수행해야 합니다."}},
[2459] = {"꿈을 먹어치우는 페로시타스", {"돌라나르에 있는 탈론카이 스위프트루트가 나무옹이일족 비술사 7명을 처치하고 잃어버린 보석을 찾아달라고 부탁했습니다."}},
[2460] = {"검은손 도적단 경례", {"셴툴에게 검은손 도적단 /경례를 해 보이십시오."}},
[2478] = {"미션 임파서블: 잘하면 가능", {"현장감독 실릭시즈에게서 실릭시즈의 탑 열쇠를 훔쳐낸 다음, 돌연변이 투자개발회사 일꾼 2명과 투자개발회사 순찰대원 2명, 그리고 투자개발회사 망꾼 2명을 처치해야 합니다.","","총감독 갤리윅스를 암살하고 그의 머리카락을 손에 넣은 후, 갤리윅스의 금고를 열고 잔질의 변화된 혼합물을 훔쳐내야 합니다. 그 혼합물과 갤리윅스의 머리카락을 오그리마에 있는 셴툴에게 가져다주고 다음 지시를 받으십시오."}},
[2479] = {"히노트의 도움", {"힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다.","","타렌 밀농장으로 가려면 먼저 비행선을 타고 언더시티로 가야 합니다. 도착하면 남쪽 길을 따라 은빛소나무 숲을 지나 힐스브래드 쪽으로 가야 합니다. 표지판을 따라 가십시오!"}},
[2480] = {"히노트의 도움", {"서지 히노트가 해독제를 만드는 동안 기다려야 합니다."}},
[2498] = {"데날란에게 돌아가기", {"레엘리안 그린스파이어가 알아메스 호수에 있는 데날란과 대화할 것을 부탁했습니다."}},
[2499] = {"오크나무괴물", {"알아메스 호수에 사는 데날란이 오크나무괴물에게서 거대한 종양을 모아 달라고 부탁했습니다."}},
[2500] = {"황야의 땅에서 재료 찾기", {"황야의 땅에서 필요한 재료를 구한 후 텔사마에 있는 가크 힐터치에게 돌아가야 합니다."}},
[2501] = {"황야의 땅에서 재료 찾기", {"빈 요술 유리병을 황야의 땅에 있는 화염의 수호비룡에게 사용해야 합니다. 3개를 다 채우면 텔사마에 있는 가크 힐터치에게로 가져가야 합니다."}},
[2518] = {"달의 눈물", {"다르나서스의 달의 신전에 있는 여사제 아무라가 여왕거미 사스라의 은빛 돌기를 가져다 달라고 부탁했습니다."}},
[2519] = {"달의 신전", {"수녀 아퀴네가 달의 신전에 있는 여사제 아무라와 대화할 것을 부탁했습니다."}},
[2520] = {"사스라의 제물", {"여사제 아무라가 달의 신전 중앙에 있는 샘에 사스라의 은빛 돌기를 제물로 바치고 돌아와 달라고 부탁했습니다."}},
[2541] = {"잠자는 드루이드", {"바네실 지하굴에 있는 오벤 레이지클로에게 부두교 주술사 부적을 가져다주어야 합니다."}},
[2561] = {"발톱의 드루이드", {"오벤 레이지클로가 영혼을 잃어버린 그의 육체를 죽인 후 부두교 부적을 사용하라고 부탁했습니다."}},
[2601] = {"바실리스크의 내장", {"혈법사 린노어에게 바실리스크 뇌 10개와 독수리 모래주머니 2개를 가져가야 합니다."}},
[2603] = {"독수리의 면역력", {"혈법사 린노어에게 독수리 모래주머니 10개와 칼송곳니하이에나 턱 2개를 가져가야 합니다."}},
[2605] = {"목마른 고블린", {"가득 찬 이슬샘을 모아 가젯잔에 있는 마린 노겐포저에게 가져가야 합니다."}},
[2606] = {"맛의 달인", {"마린 노겐포저가 가젯잔에 있는 스프링클과 대화할 것을 부탁했습니다."}},
[2607] = {"잔질의 손길", {"병영 지하실에 있는 닥 믹실픽실과 대화해야 합니다."}},
[2608] = {"잔질의 손길", {"닥 믹실픽실에게 검사를 받으려면 \"/누워\"야 합니다. 믹실픽실은 원인도 모르는 병의 치료법을 어떻게 찾을 수 있을까요?"}},
[2609] = {"잔질의 손길", {"닥 믹실픽실에게 수수한 야생화, 가연 약병 1개, 청동관 1개, 그리고 밝은 황록색 비단 실타래 1개를 가져가야 합니다. '그것'은 저절로 낫지 않는 병인 것 같습니다."}},
[2621] = {"명예를 잃은 자", {"스토나드에 있는 파견사령관 루아그와 대화하십시오."}},
[2622] = {"잃어버린 명령서", {"벤고르와 대화하십시오."}},
[2623] = {"수다쟁이 늪지멀록", {"대족장의 명령서를 회수해 호드 영웅의 넋에게 가져가야 합니다."}},
[2641] = {"스프링클의 비밀 재료", {"가젯잔에 있는 스프링클이 제비수염버섯을 하나 구해 가지고 올 것을 부탁했습니다."}},
[2661] = {"마린에게 배달", {"스프링클이 가젯잔에 있는 마린 노겐포저에게 제비수염 가루를 가져가라고 부탁했습니다."}},
[2662] = {"노겐포저의 비약", {"마린 노겐포저가 비약이 완성되길 잠시 기다렸다가 다시 말을 걸어 달라고 부탁했습니다."}},
[2681] = {"속박의 돌", {"라젤리크의 하수인 9명, 세바인의 하수인 3명, 알리스타즈의 하수인 3명, 그롤의 하수인 3명을 해방시킨 후, 호드 영웅의 넋에게 돌아가야 합니다. 돌 가까이 있지 않으면 임무에 실패하게 됩니다."}},
[2741] = {"고성능 자동부화기", nil},
[2742] = {"갇혀 있는 린지", {"린지를 호위해 쿠엘다닐 오두막을 빠져나간 후 그가 동쪽에 전망대 절벽에 숨겨두었다는 비밀 물건을 찾아내십시오."}},
[2745] = {"성 잠입", {"스톰윈드 성에 있는 티리온과 대화해야 합니다."}},
[2746] = {"변장에 필요한 물건", {"스톰윈드에 있는 티리온에게 비단 옷감 3개와 클라라의 싱싱한 사과 2개를 가져가야 합니다."}},
[2747] = {"비범한 알", nil},
[2748] = {"좋은 알", nil},
[2751] = {"야만전사의 갑옷", {"오그리마에 있는 오로크 오모쉬에게 청동 무늬 팔보호구 2개, 청동 대검 2개, 날카로운 발톱 2개를 가져다주어야 합니다."}},
[2752] = {"강철 어깨갑옷", {"오그리마에 있는 오로크 오모쉬에게 청동 전투도끼 4개와 청동 전투해머 4개를 가져다주어야 합니다."}},
[2753] = {"발 밑의 적", {"오그리마에 있는 오로크 오모쉬에게 녹색 철제 투구 4개, 녹색 철제 팔보호구 4개, 녹색 철제 다리보호구 2개를 가져다주어야 합니다."}},
[2754] = {"광란의 뿔", {"오그리마에 있는 오로크 오모쉬에게 튼튼한 철제 마울 2개, 은도금한 청동 장화 2개, 그리고 은도금한 청동 장갑 2개를 가져다주어야 합니다."}},
[2766] = {"OOX-22/FE 수색", {"거친흉터 골짜기에 있는 오글소프의 유도 로봇에게 조난 탐지기를 가져가야 합니다."}},
[2767] = {"OOX-22/FE 구출!", {"잊혀진 해안에 있는 부두까지 OOX-22/FE를 호위해 간 후 무법항에 있는 오글소프 오브노티쿠스에게 보고해야 합니다."}},
[2768] = {"자동 탐사막대", {"가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다."}},
[2769] = {"브라스볼츠 형제", {"소금 평원에 있는 위즐 브라스볼츠와 대화하십시오."}},
[2770] = {"가즈릴라", {"소금 평원에 있는 위즐 브라스볼츠에게 가즈릴라의 전기 비늘을 가져가야 합니다."}},
[2781] = {"현상수배: 칼리프 스콜피드스팅", {"칼리프 스콜피드스팅을 처치하고 그 증거로 그의 머리카락을 칼리프 스콜피드스팅의 머리카락을 가져다주어야 합니다."}},
