[3522] = {"이베론을 위한 해독제", {"제한 시간이 지나기 전에 이베론에게 해독제를 가져다줘야 합니다. 이베론은 북쪽에 있는 동굴 옆에서 찾을 수 있습니다."}},
[3523] = {"가시덩굴 구릉의 스컬지", {"그가 당신에게 서약의 돌을 줄 것입니다. 벨리스트라즈의 계획을 돕는 것에 동의하면 다시 그와 대화하여 그에게 서약의 돌을 돌려주십시오."}},
[3524] = {"해변으로 올라온 바다 생물", {"아우버다인 바로 남쪽에 있는 떠내려온 바다 생물에게서 바다 생물 뼈를 회수한 후, 아우버다인에 있는 그웨니스 블리레곤드에게 가져가야 합니다."}},
[3525] = {"우상 진화", {"가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다.","","우상을 진화하는 의식을 수행하는 동안 벨리스트라즈를 보호해야 합니다."}},
[3527] = {"모쉬아루의 예언", {"타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다."}},
[3528] = {"학카르의 화신", {"타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니<name>."}},
[3566] = {"일어나라, 흑요암이여!", {"검은 라소릭과 흑요암을 쓰러뜨리고, 그 증거로 검은 라소릭의 머리카락과 흑요암 심장을 아이언포지에 있는 소리우스에게 가져가야 합니다."}},
[3567] = {"높은 곳", nil},
[3568] = {"스며드는 타락", {"아즈샤라에 있는 엘<name>라스 폐허의 해변을 따라 가면서 4개의 빈 약병에 해일의 구덩이의 물을 모두 채운 후, 연금술사 큘리에게 돌아가야 합니<name>."}},
[3636] = {"빛의 힘", {"대주교 베네딕투스가 가시덩굴 구릉에 있는 혹한의 암네나르를 처치해달라고 부탁했습니다."}},
[3661] = {"엘룬의 피조물", {"에렐라스 앰버스카이를 위해 동부 내륙지에서 올빼미야수 깃털 15개를 모아야 합니다."}},
[3681] = {"신앙의 고서", {"스톰윈드에 있는 두소리안 랄과 대화하십시오."}},
[3701] = {"불타는 타우릿산의 폐허", {"불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다."}},
[3702] = {"불타는 타우릿산의 폐허", {"왕실사학자 아케소누스가 들려 주는 타우릿산의 역사를 들어야 합니다."}},
[3741] = {"힐러리의 목걸이", {"힐러리의 목걸이를 찾아 레이크샤이어에 있는 힐러리에게 가져가야 합니다."}},
[3761] = {"운고로 토양", {"썬더 블러프에 장로의 봉우리 있는 게드에게 운고로 토양 20개를 가져가야 합니다."}},
[3762] = {"대드루이드 룬토템 돕기", {"썬더 블러프에 있는 대<name>이드 하뮬 룬토템과 대화해야 합니다."}},
[3764] = {"운고로 토양", {"다르나서스의 세나리온 자치령에 있는 제날에게 운고로 토양 20개를 가져가야 합니다."}},
[3765] = {"먼 곳에 퍼진 타락", {"아우버다인에 있는 게르샬라 나이트위스퍼를 찾아가야 합니다."}},
[3781] = {"여명초 연구", {"다르나서스의 세나리온 자치령에 있는 마스렌길 베어워커에게 대드루이드의 씨앗 교환권을 가져가야 합니다."}},
[3783] = {"깜짝 기계설인 대작전", {"두꺼운 설인 모피 10개를 모아 눈망루 마을에 있는 우미 럼플스니커에게 갖다주어야 합니다."}},
[3784] = {"대드루이드 룬토템 돕기", {"썬더 블러프에 있는 대드루이드 하뮬 룬토템과 대화해야 합니다."}},
[3785] = {"여명초 연구", {"탈렌드리스 씨앗 꾸러미와 늘푸른 주머니를 운고로 토양 2개에 사용하여 여명초 견본을 재배하십시오.","","다르나서스에 있는 마스렌길 베어워커에게 여명초 10개를 가져가야 합니다."}},
[3789] = {"대드루이드 스테그헬름 돕기", {"다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화해야 합니다."}},
[3801] = {"검은무쇠 유물", {"도시 주요 <name>역으<name> 통하는 열쇠를 얻고 싶다면 프랑클론 포<name>라이트와 대화하십시오."}},
[3802] = {"검은무쇠 유물", {"파이너스 다크바이어를 처치하고 거대한 망치, 무쇠<name>옥을 회수해야 합니다. 무쇠<name>옥을 타우릿산의 제단으<name> 가져가서 프랑클론 포<name>라이트의 석상에 두어야 합니다."}},
[3821] = {"우레망치 바위굴", {"불타는 평원으로 가서 샤니 프라우드터스크에게 무슨 일이 있었는지 확인해야 합니다."}},
[3823] = {"불자루 오우거 처치", {"불자루일족 오우거마법사 15마리, 불자루 오우거 7마리, 불자루일족 투사 7마리를 처치한 후 랄리우스에게 돌아가야 합니다."}},
[3824] = {"포악한 군주 고르테쉬", {"우레망치 바위굴의 서쪽 어딘가에서 고르테쉬를 찾아 처치하고 고르테쉬의 가면을 얻어 불타는 평원에 있는 랄리우스에게 가져가야 합니다."}},
[3825] = {"창에 꽂은 오우거 가면", {"고르테쉬의 가면을 가지고 가서 우레망치 바위굴의 꼭대기에 꽂아야 합니다. 창을 꽂을 부드러운 흙으로 덮인 고분을 찾도록 하십시오."}},
[3844] = {"아무도 모르는 비밀", {"연못을 둘러보고 이 난파된 나룻배의 주인에 대한 단서를 찾아야 합니<name>."}},
[3845] = {"아무도 모르는 비밀", {"가방 안에 든 물건을 조사해 그 주인에게 되돌려주어야 합니<name>."}},
[3861] = {"꼬꼬댁!!!", {"특별 닭모이를 찾아 친구가 된 닭에게 돌아가야 합니다. 특별 닭모이를 주기 전에 닭을 찾으면 /환호해야 합니다."}},
[3884] = {"윌리덴의 일지", {"운고로 분화구 어딘가에 있는 윌리덴 마샬에게 일지를 돌려줘야 합니<name>."}},
[3901] = {"덜그럭거리는 해골 처치", {"덜그럭거리는 해골 12명을 처치한 후, 데스넬에 있는 어둠의사제 사비스에게 돌아가야 합니다."}},
[3902] = {"데스넬에서의 폐품 수집", {"데스넬과 그 주변에서 쓸만한 물건 6개를 찾아 죽음경비병 살테인에게 돌아가야 합니다."}},
[3903] = {"밀리 오스워드", {"밀리 오스워드와 대화해야 합니다."}},
[3904] = {"밀리의 수확물", {"노스샤이어 수도원에 있는 밀리 오스워드에게 밀리의 수확물 8 상자를 가져가야 합니다."}},
[3905] = {"포도 수확 목록", {"노스샤이어 수도원에 있는 수사 닐스에게 포도 수확 목록을 가져가야 합니다."}},
[3906] = {"화염의 부조화", {"검은바위 산에 있는 채석장으로 가서 멸망의 파이론을 처치해야 합니다. 이 임무를 완수한 후 썬더하트에게 돌아가십시오."}},
[3908] = {"아무도 모르는 비밀", {"여명의 설원에 있는 도노바 스노우덴에게 링쿠의 훈련용 검을 가져가야 합니다."}},
[3909] = {"앞날의 비약", {"페랄라스 북쪽에서 그레간 브루스퓨를 찾아야 합니다. 그에게서 앞날의 비약을 얻는 방법을 배워 여명의 설원에 있는 도노바 스노우덴에게 돌아가야 합니다."}},
[3921] = {"웨니키 볼트버킷", {"웨니키 볼트버킷에게 부서진 사모플랜지를 가져가야 합니다."}},
[3922] = {"용접용 철괴", {"불모의 땅에 있는 웨니키 볼트버킷에게 용접용 철괴 15개를 가져가야 합니다."}},
[3923] = {"릴리 그리지가브", {"오그리마에 있는 릴리 그리지가브에게 부서지고 찌그러진 사모플랜지를 가져가야 합니다."}},
[3924] = {"사모플랜지 설명서", {"오그리마에 있는 릴리 그리지가브에게 사모플랜지 설명서를 가져가야 합니다."}},
[4021] = {"반격!", {"크로스로드 서쪽에 있는 렉타르 데스게이트에게 크롬자르의 깃발 조각을 가져가야 합니다."}},
[4022] = {"화염의 맛", {"벨라로크 윈드블레이드에게서 받은 검은용군단 허물을 키루스 테레펜터스에게 보여줘야 합니다."}},
[4024] = {"화염의 맛", {"검은바위 나락으로 가서 밸가르를 처치하십시오.","","이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다.","","키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다."}},
[4081] = {"죽음의 본보기: 검은무쇠 드워프", nil},
[4102] = {"악령의 숲 정화", {"악령의 숲에 있는 메이베스 리버브리즈에게 핏빛 호박석 15개를 가져가야 합니다."}},
[4120] = {"타락의 힘", {"페랄라스의 모자케 야영지에 있는 탈로 쏜후프가 악령의 숲에 있는 성난발톱불곰 12마리와 갈퀴발톱 악령발늑대 12마리를 처치해 달라고 부탁했습니다."}},
[4123] = {"산의 정수", {"불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다."}},
[4126] = {"헐레이 블랙브레스", {"카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다."}},
[4128] = {"라그나르 썬더브루", {"라그나르 썬더브루와 대화해야 합니다."}},
[4133] = {"비비안 라그레이브", {"카르가스에 있는 비비안 라그레이브와 대화해야 합니다."}},
[4135] = {"고통의 구덩이", {"라스칼의 마지막 행방을 알아냈으니 고통의 구덩이에서 그를 찾아야 합니다. 그의 쪽지에 따르면 고통의 구덩이는 덩굴발일족 놀 야영지의 남쪽에 있습니다."}},
[4136] = {"리블리 스크류스피곳", {"리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다."}},
[4161] = {"칼도레이 조리법", {"작은 거미 다리 7개를 모아 돌라나르에 있는 자린에게 갖다주어야 합니다."}},
[4182] = {"용혈족의 위협", {"검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다."}},
[4183] = {"진정한 지도자", {"레이크샤이어로 가서 집정관 솔로몬에게 헬렌디스 리버혼의 편지를 전달해야 합니다."}},
[4184] = {"진정한 지도자", {"스톰윈드로 가서 대영주 볼바르 폴드라곤에게 볼바르에게 보내는 솔로몬의 탄원서를 전해주어야 합니다.","","볼바르는 스톰윈드 왕궁에 있습니다."}},
[4185] = {"진정한 지도자", {"여군주 카트라나 프레스톨과 얘기를 나눈 후, 대영주 볼바르 폴드라곤과 대화하십시오."}},
[4186] = {"진정한 지도자", {"레이크샤이어에 있는 집정관 솔로몬에게 볼바르의 명령서를 가져가야 합니다."}},
[4223] = {"진정한 지도자", {"불타는 평원에 있는 치안대장 맥스웰과 대화하십시오."}},
[4224] = {"진정한 지도자", {"털보 존을 만나 치안대장 윈저의 행방에 대해서 알아낸 다음 치안대장 맥스웰에게 돌아가 보고해야 합니다.","","치안대장 맥스웰은 북쪽에 있는 동굴에서 털보 존을 찾아보라고 했습니다."}},
[4241] = {"치안대장 윈저", {"북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다.","","털보 존은 윈저가 감옥으로 끌려갔다고 했습니다."}},
[4242] = {"실망", {"치안대장 맥스웰에게 나쁜 소식을 전해줘야 합니다."}},
[4262] = {"멸망의 파이론", {"멸망의 파이론을 처치한 후 잘린다 스프리그에게 돌아가야 합니다.","","잘린다가 말하기를 파이론은 채석장을 지키고 있다고 하니 그곳을 수색해야 할 것 같습니다."}},
[4263] = {"인센디우스!", {"검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다."}},
[4264] = {"꼬깃꼬깃한 쪽지", {"방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을<name>도 모릅니다."}},
[4282] = {"잔존하는 희망", {"치안대장 윈저의 잃어버린 단서를 가져 와야 합니다.","","치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포<name>가 이 정보를 가<name>고 있을 것이라 생각합니다."}},
[4283] = {"50개의 메달", {"랄리우스가 검은바위부족 메달 50개를 가져다 달라고 부탁했습니다. 불타는 평원에 있는 오크들에게서 메달을 구할 수 있는 가능성이 큽니다."}},
[4286] = {"좋은 물건", {"검은바위 나락으로 가서 검은무쇠 부족 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다."}},
[4289] = {"운고로의 유인원", {"운고로 분화구 입구에 있는 토르와 패스파인더에게 운고로 고릴라 모피 2개, 운고로 우레고릴라 모피 2개, 운고로 천둥고릴라 모피 2개를 가져가야 합니<name>."}},
[4290] = {"라르코르위의 먹이", {"라르코르위가 막 잡은 사냥감을 찾아 트레샤돈 시체 덩이를 훔친 후 운고로 분화구에 있는 토르와 패스파인더에게 돌아가야 합니<name>."}},
[4291] = {"라르코르위의 냄새", {"운고로 분화구 입구에 있는 토르와 패스파인더에게 라바사우루스 페로몬샘 2개를 가져가야 합니<name>."}},
[4293] = {"진흙괴물 견본...", {"악령의 숲에 있는 진흙괴물에게서 악령의 숲 진흙괴물 견본을 모은 후 언더시티의 연금술사 퓰리 옆에 있는 실험 기구를 사용해 어느 견본이 가장 부패한 것들인지 알아내야 합니<name>. 부패한 악령의 숲 견본 5개를 찾으면 연금술사 퓰리에게 가져가야 합니<name>."}},
[4296] = {"일곱 현자의 서판", {"불타는 평원에 있는 맥스워트 우버글린트에게 서판 사본을 가져가야 합니다."}},
[4300] = {"발톱으로 만든 무기", {"오그리마에 있는 제스리몬에게 라바사우루스의 흰발톱 8개를 가져가야 합니다."}},
[4322] = {"탈옥!", {"치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오."}},
[4324] = {"유카 스크류스피곳", {"불타는 평원에 있는 유카 스크류스피곳과 대화해야 합니다."}},
[4341] = {"카란 마이트해머", {"검은바위 나락으로 가서 카란 마이트해머를 찾아야 합니다.","","국왕은 카란이 그곳에 포로로 잡혀 있을 것이라고 말했습니다. 그곳 감옥을 찾아보는 것이 좋겠습니다."}},
[4342] = {"카란의 이야기", {"카란 마이트해머가 하는 이야기를 들어야 합니다."}},
[4361] = {"나쁜 소식 전달", {"아이언포지로 돌아가 국왕 마그니 브론즈비어드에게 이 나쁜 소식을 전해야 합니다."}},
[4402] = {"갈가르의 선인장 사과 별미", {"갈가르에게 선인장 사과 10개를 가져가야 합니다. 선인장 근처에서 찾을 수 있다고 한 말이 기억납니다."}},
[4449] = {"화장실에 갇힌 사람", {"검은무쇠 지질학자 8명을 처치하고 이글거리는 협곡의 화장실에 갇힌 사람에게 비단 옷감 15개를 가져가야 합니다."}},
[4450] = {"타나리스의 장부", {"굿스틸 장부를 가지고 거기에 적힌 물건들을 다 모은 다음 타나리스에 있는 크린클 굿스틸을 찾아가야 합니다."}},
[4451] = {"자유의 열쇠", {"이글거리는 협곡을 탐색해서 검댕가루 화장실 열쇠의 용도를 알아내야 합니다."}},
[4494] = {"실리시드의 행진", {"가젯잔에 있는 연금술사 페슬저그와 대화하십시오."}},
[4495] = {"죽마고우", {"북쪽의 동굴 근처에서 이베론을 찾아야 합니다."}},
[4502] = {"화산 활동", {"운고로 분화구의 화산 주위에 있는 불의 정령에게서 운고로 재 견본 9개를 모아 톱니항에 있는 리브 리즐픽스에게 가져가야 합니다."}},
[4504] = {"초강력 접착제", {"매우 끈적거리는 타르 12개를 모아 가젯잔에 있는 트란렉에게 갖<name> 주어야 합니<name>."}},
[4505] = {"오염된 달샘", {"비취불꽃의 사티로스가 지키는 달샘에서 오염된 물 견본을 채취하여 피멍울 초소에 있는 위나 해저드에게 가져가야 합니다."}},
[4506] = {"오염된 고양이", {"위나의 고양이를 오염된 달샘으로 데려가서 풀어 준 다음 위나에게 다시 데려가야 합니다.","","위나에게로 데려간 후 클릭하면 위나에게 돌아갈 것입니다."}},
[4512] = {"수액괴물 견본 수집", {"아이언포지에 있는 라리스 기어더들에게 가득찬 저주받은 수액괴물 병 6개와 가득찬 부패한 수액괴물 병 6개를 가져가야 합니다."}},
[4521] = {"사나운 수호병", {"악령의 숲에 있는 트룰 페일베인이 흉포한 올빼미야수 15마리, 그리고 털복숭이 올빼미야수 15마리를 처치해달라고 부탁했습니다."}},
[4542] = {"높새바람 봉우리", {"긴급 전갈을 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 가져가야 합니다."}},
[4581] = {"케이네스 스틸윈드", {"숲의 노래에 있는 케이네스 스틸윈드에게 신드렐의 쪽지를 가져가야 합니다."}},
