[4740] = {"현상수배: 먹구렁", {"먹구렁이라는 멀록을 찾아서 처치해야 합니다. 이 괴물은 아우버다인 남쪽, 해안에서 멀록 오두막을 보호하고 있는 것으로 추정됩니다.","","먹구렁을 처치하면 아우버다인에 있는 파수꾼 글린다 날셰에게 보고하십시오."}},
[4761] = {"툰드리스 윈드위버", {"아우버다인에 있는 툰드리스 윈드위버와 대화하십시오."}},
[4762] = {"폭포수 강", {"아우버다인 북쪽으로 가서 폭포수 강 가장자리에 있는 첫 번째 폭포에서 물 견본을 채취해야 합니다.","","폭포수 강물 견본을 가지고 아우버다인에 있는 툰드리스 윈드위버에게 돌아가십시오."}},
[4763] = {"타락한 검은나무일족", {"아우버다인 달샘의 물로 빈 정화의 그릇을 채우십시오.","","검은나무일족 펄볼그 북부 야영지에서 검은나무일족 과일 견본, 검은나무일족 열매 견본, 검은나무일족 곡식 견본을 모으십시오.","","물과 음식을 한데 섞어 북부 야영지의 폭포수 강에서 가장 가까운 화톳불 근처에 두면 사티로스 타락자를 불러낼 수 있습니다.","","부패의 부적을 손에 넣은 후 아우버다인에 있는 툰드리스 윈드위버에게 가져가십시오."}},
[4767] = {"와이번 조련사", {"높새바람 봉우리에 있는 엘루에게 마루둥지 와이번 알 10개를 가져가야 합니다."}},
[4770] = {"집으로", {"마루둥지에 있는 파오카 스위프트마운틴을 호위해 간 다음 백사장 야영지에 있는 모테가 파이어메인과 대화하십시오."}},
[4781] = {"흑마법사의 로브", {"가시덤불 골짜기에 있는 시즈크 굿스티치에게 금괴 하나를 가져가야 합니다."}},
[4787] = {"고대의 알", {"고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다."}},
[4808] = {"펠노크 스틸스프링", {"팅키의 편지를 펠노크 윈터스프링에게 가져다주어야 합니다."}},
[4809] = {"서리바람 키메라의 뿔", {"펠노크 윈터스프링에게 온전한 서리바람 키메라의 뿔 8개를 가져가야 합니다."}},
[4811] = {"붉은 수정", {"어둠의 해안의 동쪽 산맥을 따라 아우버다인 동쪽으로 가서 거대한 붉은 수정을 찾은 다음 아우버다인에 있는 파수꾼 글린다 날셰에게 보고해야 합니다."}},
[4812] = {"수정에 물이 흐르면", {"빈 시험관에 아우버다인의 달샘 물을 채운 후 어둠의해안의 동쪽 산에 있는 붉은 수정을 찾아 조사하십시오."}},
[4813] = {"수정 안의 뼈", {"아우버다인에 있는 파수꾼 글린다 날셰에게 알아 낸 사실을 보고해야 합니다."}},
[4821] = {"괴상한 알", {"높새바람 봉우리에 있는 하가르 라이트닝후프에게 괴상한 알을 가져가야 합니다."}},
[4841] = {"켄타우로스 처치", {"갈라크일족 척후병 12명, 갈라크일족 사냥꾼 10명, 갈라크일족 바람전사 6명을 처치한 후, 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 돌아가야 합니다."}},
[4842] = {"이상한 근원", {"도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오."}},
[4861] = {"성난 올빼미야수", {"여명의 설원 남부 <name>역에서 야론 스톤셰이퍼의 야영<name>를 찾아서 부서진 보급품 상자를 되찾아 와야 합니다."}},
[4862] = {"더러운 거미알", {"검은바위 첨탑으로 가서 키블러를 위해 첨탑 거미알 15개를 수집해야 합니다.","","들리는 소문으로는 그 알들은 거미들이 서식하는 근처에서 찾을 수 있다고 합니다."}},
[4863] = {"성난 올빼미야수", {"야론 스톤셰이퍼의 부서진 마차를 찾아야 합니다."}},
[4864] = {"성난 올빼미야수", {"눈 속에서 야론의 보급품을 회수한 다음, 야론이 찾는 아뮬렛을 훔친 올빼미야수들을 찾아야 합니다.","","여명의 설원, 별똥별 마을에 있는 야론 스톤셰이퍼에게 야론의 보급품과 푸른 깃털달린 아뮬렛을 갖다주어야 합니다."}},
[4865] = {"뱀의 복수", {"발견한 사실을 모테가 파이어메인에게 보고해야 합니다."}},
[4866] = {"여왕거미의 독", {"검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다."}},
[4881] = {"암살 음모", {"백사장 야영지에 있는 카나티 그레이클라우드에게 가서 암살 음모에 대해 경고해 주어야 합니다."}},
[4904] = {"마침내 자유를", {"라코타 윈드송을 먹구름 봉우리에서 구출한 후, 높새바람 봉우리에 있는 탈리아 앰버하이드와 대화하십시오."}},
[4921] = {"전쟁으로 잃은 아내", {"크로스로드에 있는 만크릭을 위해 그의 아내의 흔적을 찾아 돌아가야 합니다."}},
[4963] = {"지옥불정령의 영혼", {"지옥불 에메랄드를 가지고 가서 잊혀진 땅의 지옥불정령 중 하나에게 사용해 영혼을 사로 잡아야 합니다. 성공하면 지옥불 에메랄드와 사로잡은 지옥불정령의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다."}},
[4965] = {"오라힐 보주의 지혜", {"불모의 땅에 있는 미네라 보이드렌더와 대화하십시오."}},
[4966] = {"카나티 그레이클라우드 보호", {"켄타우로스의 공격으로부터 카나티 그레이클라우드를 보호해야 합니다."}},
[4969] = {"오라힐 보주의 지혜", {"불모의 땅에 있는 미네라 보이드렌더와 대화하십시오."}},
[4971] = {"시간 문제", {"안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오.","","시간의 기생충 15마리를 처치한 후, 서부 역병지대의 안돌할 여관에 있는 크로미에게 시간의 재배열기를 가져가야 합니다."}},
[5021] = {"늦어버린 소포 배달", {"유령 여인의 두서없는 말을 들으니 소포를 전달해야 했던 것 같습니다. 자신의 말이 있던 곳에 소포가 있다고 했는데, 말이 어디 있는지, 그리고 소포를 어디로 전달해야 하는지에 대해서는 이해할 수 없는 말만 늘어놓습니다."}},
[5023] = {"늦어버린 소포 배달", {"언더시티의 왕실감독원과 대화하여 제레미어 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 길드 사무소 근처에 있습니다."}},
[5041] = {"크로스로드의 보급품", {"크로스로드 보급품 상자를 찾아서 불모의 땅의 톨크에게 가져가 주어야 합니다."}},
[5042] = {"아감마간의 힘", nil},
[5043] = {"아감마간의 민첩성", nil},
[5044] = {"아감마간의 지혜", nil},
[5045] = {"정신력 상승", nil},
[5046] = {"서슬가죽", nil},
[5049] = {"우울한 제레미어", {"언더시티에서 제레미어 페이슨을 찾아 그가 정말로 제레미어 펠스톤인지 확인하십시오. 그가 정말로 제레미어 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다."}},
[5050] = {"행운의 부적", {"서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다."}},
[5052] = {"아감마간의 혈석 파편", {"불모의 땅의 타우라조 야영지에 있는 뻐드렁니에게 혈석을 가져가야 합니다.","","아감마간의 힘을 빌린 축복을 받고 싶다면 최대한 많이 수집해야 합니다."}},
[5054] = {"톱니이빨곰 우르시우스", {"여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 우르시우스를 처치해달라고 요청했습니다."}},
[5055] = {"서리바람 브룸랜", {"여명의 설원 눈망루 마을에 있는 스톰 섀도후프가 브룸랜을 처치해 달라고 요청했습니다."}},
[5058] = {"달슨 부인의 일기", nil},
[5059] = {"잠긴 화장실", nil},
[5060] = {"잠긴 장롱", nil},
[5061] = {"수중 동물 변신", {"다르나서스로 돌아가 마스렌길 베어워커에게 바다표범의 펜던트를 보여 주어야 합니다."}},
[5062] = {"신성한 불", {"불꽃 용설란 10포기를 모아 썬더 블러프 장로의 봉우리에 있는 마가타 그림토템을 찾아가야 합니다."}},
[5064] = {"그림토템부족 염탐", {"먹구름 봉우리에 있는 비밀 쪽지 3개를 찾아 와야 합니다."}},
[5065] = {"모쉬아루의 잃어버린 서판", {"세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다."}},
[5082] = {"눈사태일족의 위협", {"여명의 설원에 있는 도노바 스노우덴이 눈사태일족 길잡이 8마리, 눈사태일족 보초 8마리, 눈사태일족 토템술사 8마리를 처치해달라고 요청했습니다."}},
[5083] = {"눈사태일족 화주", {"여명의 설원에 있는 도노바 스노우덴에게 빈 화주 시험관을 갖다주어야 합니다."}},
[5084] = {"타락에 빠지다", {"악령의 숲 북부에 있는 마른가지일족 펄볼그 야영지에서 단서를 찾아야 합니다."}},
[5085] = {"신비한 액체", {"발견한 사실을 도노바 스노우덴에게 알려야 합니다."}},
[5086] = {"맹독 정령", {"여명의 설원에 있는 도노바 스노우덴에게 맹독 정령 수액 3개를 갖다주어야 합니다."}},
[5087] = {"눈사태일족 정찰꾼", {"눈사태일족 정찰꾼들을 찾아 눈사태일족 마을로 물건을 전달하는 것을 막아야 합니다."}},
[5088] = {"아리카라", {"아리카라를 쓰러뜨려야 합니다. 그 증거로 그녀의 유해와 불꽃 가루를 백사장 야영지에 있는 모테가 파이어메인에게 가져가야 합니다."}},
[5095] = {"역병지대 징집령!", {"고위집행관 델링턴을 찾아가야 합니다. 그의 주둔지는 티리스팔 숲과 언더시티의 동쪽에 있는 보루에 있습니다."}},
[5096] = {"붉은십자군의 주의 끌기", {"펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오.","","기지에 스컬지 깃발을 세운 후, 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 돌아가야 합니다."}},
[5098] = {"감시탑 공격 준비", {"신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.","","네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 가져가십시오."}},
[5121] = {"대부족장 눈사태", {"여명의 설원에 있는 도노바 스노우덴이 대부족장 눈사태를 처치해 달라고 부탁했습니다."}},
[5123] = {"마지막 단서", {"여명의 설원에 있는 도노바 스노우덴에게 휘갈겨 쓴 일지를 가져다주어야 합니다."}},
[5128] = {"대부족장의 기록", {"악령의 숲 남부에 있는 켈레크 스카이키퍼에게 휘갈겨 쓴 일지를 갖다주어야 합니다."}},
[5142] = {"꼬마 파멜라", {"파멜라 레드패스를 찾아야 합니다."}},
[5147] = {"현상 수배: 아르낙 그림토템", {"아르낙 그림토템을 처치하고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 그 증거물을 갖다주어야 합니다."}},
[5149] = {"파멜라의 인형", {"파멜라의 인형을 찾아야 합니다."}},
[5151] = {"초전도 장치", {"퓨마를 처치하고 초전도 장치와 퓨마 우리 열쇠를 위즐로 베어링샤이너에게 돌려주어야 합니다."}},
[5152] = {"말레네 고모", {"안돌할 폐허 남쪽에서 말레네와 대화해야 합니다."}},
[5153] = {"이상한 역사가", {"조셉의 결혼반지를 크로미에게 가져가야 합니다."}},
[5154] = {"다로우샤이어 연대기", {"안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다."}},
[5155] = {"자에데나르의 힘", {"자에데나르에 가서 자에데나르 사냥개 4마리, 자에데나르 수호병 4명, 자에데나르 숙련사제 6명, 자에데나르 이교도 6명을 처치하고 그레타 모스후프에게 돌아가야 합니다."}},
[5156] = {"오염 확인", {"불벼락 골짜기를 탐색하는 동안 혼돈의 불길 2마리와 혼돈의 소산물 2마리를 처치해야 합니다. 분화구를 조사해 아직도 부패한 물이 남아 있는지 확인하고 악령의 숲의 타론 레드페더에게 돌아가야 합니다."}},
[5157] = {"부패한 물 채취", {"빈 수통을 자에데나르 중심부의 달샘으로 가져가서 채운 다음 악령의 숲에 있는 그레타 모스후프에게 가져 가야 합니다."}},
[5211] = {"다로우샤이어의 병사들", {"15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다."}},
[5228] = {"스컬지 가마솥", {"서부 역병지대의 보루에 있는 어둠의여사제 반디스와 대화해야 합니다."}},
[5229] = {"목표: 펠스톤 농장", {"서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수 있습니다. 반드시 빈 펠스톤 농장 병을 가지고 가서 가마솥 안에 있는 독의 견본을 확보해야 합니다."}},
[5230] = {"보루로의 귀환", {"서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 펠스톤 농장 병을 가져가야 합니다."}},
[5231] = {"목표: 달슨의 눈물", {"서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}},
[5232] = {"보루로의 귀환", {"서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다."}},
[5233] = {"목표: 고통의 흉가", {"서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}},
[5234] = {"보루로의 귀환", {"서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 고통의 흉가 혼합물을 가져가야 합니다."}},
[5235] = {"목표: 가론의 흉가", {"서부 역병지대의 가론의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 가론의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다."}},
[5236] = {"보루로의 귀환", {"서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다."}},
[5238] = {"임무 완료!", nil},
[5241] = {"카를린 삼촌", {"카를린 레드패스를 찾아야 합니다."}},
[5244] = {"켈테릴의 폐허", {"별똥별 마을에 있는 야론 스톤셰이퍼와 대화하십시오."}},
[5245] = {"켈테릴의 고통받는 영혼", {"야론의 곡괭이를 사용해 귀족 유물 조각 4개를 찾아 동부 역병지대에 있는 아우로라 스카이콜러에 갖다주어야 합니다."}},
[5250] = {"별똥별 마을", {"여명의 설원에서 별똥별 마을을 찾아 윈드 나이트체이서와 대화하십시오."}},
[5261] = {"이건 펠트스키너", {"이건 펠트스키너와 얘기해야 합니다."}},
[5321] = {"잠에서 깨어난 드루이드", {"케를로니안 에버셰이드를 릴라드리스 문리버가 있는 남쪽으로 호위하며, 어둠의 해안에서 그의 가방을 찾아야 합니다."}},
