[5361] = {"형제애", {"절벽파수꾼 롱혼의 보고서를 잊혀진 땅의 침묵의 초소에 있는 나타카 롱혼에게 가져가야 합니다."}},
[5381] = {"이룩소스의 손", {"천둥도끼 요새에서 악마의 상자를 찾아서 그늘수렵 마을에 있는 타이가 와이즈메인에게 가져가십시오. 악마의 곡괭이도 함께 돌려줘야 합니다."}},
[5386] = {"낚시하는 날", {"그늘수렵 마을에 있는 지나르질렌과 대화한 후 나타카 롱혼에게 붉은복어 2마리를 가져가야 합니다."}},
