[5441] = {"게으른 일꾼들", {"작업반장의 몽둥이를 가지고 가서 자고 있는 게으른 일꾼에게 사용해야 합니다. 일꾼 5명을 깨운 다음 시험의 골짜기에 있는 작업반장 타즈릴에게 돌아가 몽둥이를 돌려줘야 합니다."}},
[5481] = {"고르도의 임무", {"어둠풀 3개를 채집해 브릴 공동묘지에 있는 초보연금술사 홀랜드에게 가져가야 합니다."}},
[5482] = {"죽음풀", {"초급연금술사 홀랜드에게 죽음풀 10개를 모아서 가져가야 합니다."}},
[5501] = {"뼈 수집가", {"코르메크의 오두막에 있는 비블리 푸츠버클에게 코도 무덤에서 코도 뼈 10개를 가져가야 합니다."}},
[5535] = {"영혼의 동요", {"명가의 유령 6명과 명가의 망령 6명을 처치한 후 아즈샤라에 있는 로아투에게 돌아가십시오."}},
[5536] = {"증오로 가득 찬 땅", {"할<name>르 사티로스 6명, 할<name>르 요술사 2명, 할<name>르 악마추종자 2명을 처치한 후 잿빛 골짜기 경계에 있는 로아투에게 돌아가십시오."}},
[5541] = {"럼블샷의 탄환", {"던 모로에 있는 헤그너 럼블샷에게 럼블샷의 탄환을 가져가야 합니다."}},
[5545] = {"골칫덩어리", {"동부 벌목지에 있는 랠렌에게 장작 더미 8개를 가져가야 합니다."}},
[5561] = {"코도 길들이기", {"길들인 코도 5마리와 코도 유인기를 자신의 야영지에 있는 스미드 스크래블스크류에게 가져가야 합니다."}},
[5581] = {"악마의 차원문", {"만노로크 소굴에서 악마의 차원문 6개를 없애고 타이가 와이즈메인에게 돌아가야 합니다."}},
[5601] = {"여동생 파멜라", {"다로우샤이어에서 파멜라 레드패스를 찾아야 합니다."}},
[5621] = {"달빛 로브", {"파수꾼 샤야를 찾아 2레벨 하급 치유로 부상을 치유한 후, 신의 권능:인내를 부여하고 돌라나르에 있는 라우르나 모닝라이트에게 돌아가십시오."}},
