[5623] = {"빛의 추종자", {"엘윈 숲에 있는 여사제 조세타와 대화해야 합니다."}},
[5624] = {"성스러운 빛의 로브", {"경비병 로버트를 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 그에게 신의 권능: 인내를 부여하고 골드샤이어에 있는 여사제 조세타에게 돌아가야 합니다."}},
[5625] = {"성스러운 빛의 로브", {"산악경비대 돌프를 찾아 2레벨의 하급 치유를 사용해 부상을 치유한 후, 신의 권능:인내를 부여하고 카라노스에 있는 막산 앤볼에게 돌아가십시오."}},
