[5629] = {"귀향길", {"다르나서스에 있는 여사제 알라시아와 대화하십시오."}},
[5635] = {"구원의 기도", {"아이언포지에 있는 대사제 로한과 대화해야 합니다."}},
[5644] = {"어둠의 희생", {"언더시티에 있는 애살리스테와 대화해야 합니다."}},
[5645] = {"응징", {"아이언포지에 있는 대사제 로한과 대화하십시오."}},
