[5741] = {"빛의 홀", {"빛의 홀을 얻은 후 에텔 레소르의 탑에 있는 아조레 알다모트에게 돌아가야 합니다."}},
[5761] = {"야수 처단", {"성난불길 협곡으로 가서 욕망의 타라가만을 제거한 다음 그의 심장을 오그리마에 있는 네루 파이어블레이드에게 가져가야 합니다."}},
[5762] = {"헤멧 네싱워리", {"가시덤불 골짜기에 있는 헤멧 네싱워리에게 크레이블의 상자를 가져가야 합니다."}},
[5763] = {"가시덤불 골짜기의 사냥꾼", {"가시덤불 골짜기에 있는 헤멧 네싱워리에게 룬의 코도 뿔을 가져가야 합니다."}},
[5821] = {"경호원 고용", {"콜카르 켄타우로스 마을을 지나가는 기젤톤 대상단을 호위하고 스크래블스크류의 야영지에 있는 스미드와 대화하여 보상을 받아야 합니다."}},
[5863] = {"모래망치 주둔지", {"가젯잔에 있는 앤디 린이 모래망치일족 투사, 모래망치일족 집행자를 각각 10명씩 처치하고 파괴자 고르마로크를 처단하여 모래망치 주둔지를 없애 달라고 부탁했습니다."}},
[5881] = {"휴가 통지서", {"마그그랜이 불모의 땅 구름 승강장에 있는 그리쉬 롱러너에게 통지서를 전해달라고 부탁했습니다."}},
