[5929] = {"거대한 곰의 혼", {"달의 숲 북서쪽에 사는 거대한 곰의 혼을 찾아가 드루이드라면 반드시 알아야 할 곰의 본성에 대해 배워야 합니다. 임무를 완수하면 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 돌아가십시오."}},
