[5943] = {"기젤톤 대상단", {"만노로크 소굴을 지나가는 기젤톤 대상단을 호위하고 스크래블스크류의 야영지에 있는 스미드와 대화하여 보상을 받아야 합니다."}},
[5961] = {"밴시 여왕의 용사", {"동부 역병지대의 마리스 농장에 살고 있는 나타노스 블라이트콜러와 대화해야 합니다."}},
[6001] = {"육체와 정신", {"아우버다인의 달빛야수 비석에 세나리온 달가루를 뿌려서 초승달발톱을 불러내야 합니다. 그런 다음 초승달발톱과 대면하여 그가 가진 육체와 정신의 힘을 얻어야 합니다.","","모든 일을 마치면 다르나서스에 있는 마스렌길 베어워커와 대화하십시오."}},
[6002] = {"육체와 정신", {"초승달발톱을 불러내려면 멀고어와 불모의 땅 사이에 있는 달빛야수 비석에 세나리온 달가루를 사용해야 합니다. 거기에서 초승달발톱과 대적하여 그가 가진 육체와 마음의 힘을 얻으십시오.","","임무를 마치면 썬더 블러프에 있는 투락 룬토템과 대화해야 합니다."}},
[6021] = {"추방자 잴다르", {"잴다르를 처치하고 그 증거로 머리카락을 희망의 빛 예배당에 있는 관리인 알렌에게 가져가야 합니다."}},
[6027] = {"고대의 책", {"고대의 책을 손에 넣은 다음 에텔 레소르의 탑에 있는 아조레 알다모트에게 가져가야 합니다."}},
[6029] = {"눈망루 마을 보고서", {"서부 역병지대 보루에 있는 은빛장교 가루쉬에게 눈망루 마을 보고서를 전달해야 합니다."}},
[6030] = {"공작 니콜라스 즈바른호프", {"동부 역병지대 희망의 빛 예배당에 있는 공작 니콜라스 즈바른호프에게 \"영적인 대화에 대한 논문\"이라는 책을 전해야 합니다."}},
[6061] = {"야수 길들이기", {"조련용 막대를 사용해 다자란 초원타조를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다."}},
[6062] = {"야수 길들이기", {"조련용 막대를 사용해 사나운 점박이멧돼지를 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 조련용 막대를 돌려주어야 합니다."}},
[6063] = {"야수 길들이기", {"조련용 막대를 사용해 나무그물 늑대거미를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다."}},
[6064] = {"야수 길들이기", {"조련용 막대를 사용해 큰 멧돼지를 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 조련용 막대를 돌려주어야 합니다."}},
[6065] = {"사냥꾼의 길", {"블러드후프 마을에 있는 요 샤프메인과 대화해야 합니다."}},
[6071] = {"사냥꾼의 길", {"돌라나르에 있는 다잘라와 대화하십시오."}},
[6075] = {"사냥꾼의 길", {"카라노스에 있는 그리프 와일드하트와 대화하십시오."}},
[6081] = {"야수 길들이기", {"오그리마에 있는 오르막 그림샷과 대화하십시오."}},
[6082] = {"야수 길들이기", {"조련용 막대를 사용해 등껍질전갈을 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 돌아가십시오."}},
[6083] = {"야수 길들이기", {"조련용 막대를 사용해 붉은톱니게를 길들여야 합니다. 기술을 연습한 후 칼바위 언덕에 있는 소타르에게 조련용 막대를 돌려주어야 합니다."}},
[6084] = {"야수 길들이기", {"조련용 막대를 사용해 눈표범을 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 돌아가십시오."}},
[6085] = {"야수 길들이기", {"조련용 막대를 사용해 얼음발톱흰곰을 길들여야 합니다. 기술을 연습한 후 카라노스에 있는 그리프 와일드하트에게 조련용 막대를 돌려주어야 합니다."}},
[6086] = {"야수 길들이기", {"아이언포지에 있는 빌리아 썬더그래니트와 대화하십시오."}},
[6087] = {"야수 길들이기", {"조련용 막대를 사용해 긴발톱 초원늑대를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다."}},
[6088] = {"야수 길들이기", {"조련용 막대를 사용해 검독수리를 길들이고 기술을 연습한 후 블러드후프 마을에 있는 요 샤프메인에게 조련용 막대를 돌려줘야 합니다."}},
[6089] = {"야수 길들이기", {"썬더 블러프의 수렵의 봉우리에 있는 홀트 썬더혼과 대화해야 합니다."}},
[6101] = {"야수 길들이기", {"조련용 막대를 사용해 긴발톱 흑호를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다."}},
[6102] = {"야수 길들이기", {"조련용 막대를 사용해 비명소리 스트리기드 올빼미를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다."}},
[6103] = {"야수 길들이기", {"다르나서스의 세나리온 자치령에서 조카스테와 대화하십시오."}},
[6121] = {"새로운 가르침", {"달의 숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다."}},
[6122] = {"오염된 수원", {"빈 절벽 폭포 견본병을 이용해 폭포 옆에 있는 동굴 입구에서 물을 채취해야 합니다.","","물을 다 채우면, 아우버다인, 어둠의 해안에 있는 알란다리안 나이트송에게 가득 찬 절벽 폭포 견본병을 갖다주어야 합니다."}},
[6123] = {"약재 모으기", {"아우버다인의 알란다리안 나이트송이 치료제를 만들 수 있도록 뱀뿌리 5개와 달버섯 12개를 가져다 주어야 합니다."}},
[6124] = {"병든 사슴 치유", {"어둠의 해안에 퍼져 있는 병든 사슴 10 마리에게 잘 듣는 동물 연고를 발라 치료해야 합니다. 병든 사슴은 폭포수 강 남부에서 아우버다인 북부까지 퍼져 있으며 잿빛 골짜기가 시작되는 어둠의 해안 남부까지 넘나든다고 합니다."}},
[6125] = {"독을 다스리는 능력", {"다르나서스, 세나리온 자치령에 있는 마스렌길 베어워커에게 돌아가야 합니다."}},
[6126] = {"새로운 가르침", {"달의 숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다."}},
[6127] = {"오염된 수원", {"빈 공포의 안개봉우리 견본병을 봉우리 정상까지 가지고 가서 꼭대기 물웅덩이의 물을 채취해야 합니다.","","가득 찬 공포의 안개봉우리 견본병을 불모의 땅, 크로스로드에 있는 통가 룬토템에게 갖다주어야 합니다."}},
[6128] = {"약재 모으기", {"크로스로드의 통가 룬토템이 치료제를 만들 수 있도록 뱀뿌리 5개와 코도 뿔 5개를 갖다주어야 합니다."}},
[6129] = {"병든 가젤 치유", {"불모의 땅 북부에 퍼져 있는 병든 가젤 10마리를 찾아 잘 듣는 동물 연고를 발라서 치료해야 합니다. 병든 가젤은 크로스로드를 동서로 가로지르는 길의 북쪽에 있다고 합니다."}},
[6130] = {"독을 다스리는 능력", {"썬더 블러프 장로의 봉우리에 있는 투락 룬토템에게 돌아가야 합니다."}},
[6132] = {"멜릿자 브림버즐 구출 작전", {"멜릿자 브림버즐을 호위한 후, 잊혀진 땅의 코도 무덤에 있는 호르니즈 브림버즐과 대화해야 합니다."}},
[6134] = {"유령의 플라스마 모으기", {"잊혀진 땅의 호르니즈 브림버즐에게 유령의 플라스마 8개와 유령 유인기 상자를 가져가야 합니다."}},
[6141] = {"수사 안톤", {"잊혀진 땅에 있는 수사 안톤과 대화해야 합니다."}},
[6142] = {"조개 미끼", {"연갑 조갯살 10개를 찾은 후, 그늘수렵 마을에 있는 마이라힐에게 가져가야 합니다."}},
[6143] = {"나가 퇴치", {"뱀갈퀴일족 미르미돈 7마리, 뱀갈퀴일족 나가 7마리, 뱀갈퀴일족 여마법사 5마리를 처치한 후, 잊혀진 땅의 그늘수렵 마을에 있는 드룰제가르와 대화해야 합니다."}},
[6161] = {"랙모어의 보물을 찾아라!", {"랙모어의 은열쇠와 랙모어의 황금열쇠를 찾아 랙모어의 궤짝을 열어야 합니다."}},
[6162] = {"남편의 마지막 전투", {"대군주 로르를 처치하고 그의 발톱을 악령의 숲, 피멍울 초소에 있는 드레카술에게 가져가야 합니다."}},
[6181] = {"긴급 전갈", {"루이스의 쪽지를 가지고 그리핀 조련사 토르에게 가야 합니다."}},
[6261] = {"덩가 롱드링크", {"그리핀 조련사 덩가 롱드링크에게 오스릭의 상자를 가져가야 합니다."}},
[6281] = {"스톰윈드로 이동", {"그리핀 조련사 토르에게 요금을 지급하고 그리핀을 탄 다음 루이스의 쪽지를 스톰윈드에 있는 오스릭 스트랑에게 가져가야 합니다. 오스릭은 스톰윈드의 구 시가지에 있는 품질보증 갑옷 상점에 있습니다."}},
[6282] = {"하피의 위협", {"해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 하피, 복병, 암살자, 약탈자를 각각 7마리씩 처치해달라고 부탁했습니다."}},
[6283] = {"혈폭풍일족의 혈통", {"해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 갈퀴발톱을 처치하고 그 증거로 그녀의 유해를 가져오라고 부탁했습니다."}},
[6284] = {"거미의 공포", {"베스셀레스를 처치하고 그 증거로 베스셀레스의 송곳니를 들고 해바위 야영지의 마그그랜에게 가져가야 합니다."}},
[6285] = {"루이스에게 돌아가기", {"그리핀 조련사 덩가 롱드링크에게 요금을 지급하고 감시의 언덕으로 가는 그리핀을 탄 다음 오스릭의 상자를 감시의 언덕에 있는 루이스에게 가져가야 합니다."}},
[6301] = {"생태계의 순환", {"해바위 야영지에 있는 탐라 윈드필드가 가이아 씨앗 10개를 모아다 달라고 부탁했습니다."}},
[6321] = {"공동묘지 장비 조달", {"포드리그의 주문서를 가지고 박쥐 조련사 카로스 라조크에게 가야 합니다."}},
[6322] = {"마이클 가레트", {"고든의 상자를 마이클 가레트에게 가져가야 합니다."}},
[6323] = {"언더시티로 이동", {"박쥐 조련사 카로스 라조크에게 돈을 지급하고 언더시티로 가는 박쥐를 탄 다음 포드리그의 주문서를 언더시티에 있는 고든 웬드헴에게 가져가야 합니다."}},
[6324] = {"포드리그에게 돌아가기", {"박쥐 조련사 마이클 가레트에게 돈을 지급하고 공동묘지로 가는 박쥐를 탄 다음 고든의 상자를 공동묘지에 있는 죽음경비병 포드리그에게 가져가야 합니다."}},
[6341] = {"텔드랏실의 물고기", {"네사의 수집물을 베스프리스투스에게 가져가야 합니다."}},
[6342] = {"아우버다인으로의 비행", {"히포그리프 조련사 베스프리스투스를 통해 아우버다인까지 날아간 다음 네사의 수집물을 레어드에게 전해줘야 합니다."}},
[6343] = {"네사에게 돌아가기", {"레어드의 답장을 네사 섀도송에게 전달해야 합니다."}},
[6344] = {"네사 섀도송", {"네사 섀도송을 만나야 합니다."}},
[6361] = {"가죽 묶음", {"크로스로드에 있는 와이번 조련사 데브락에게 가죽 묶음을 가져가야 합니다."}},
[6362] = {"썬더 블러프로 날아가기", {"와이번 조련사 데브락에게 요금을 내고 썬더 블러프까지 날아간 다음 가죽 묶음을 아하누에게 전해줘야 합니다."}},
[6363] = {"와이번 조련사 탈", {"아하누의 가죽용품을 썬더 블러프에 있는 탈에게 가져가야 합니다."}},
[6364] = {"자안에게 돌아가기", {"와이번 조련사 탈에게 요금을 치르고 크로스로드까지 날아간 다음 아하누의 가죽용품을 자안 호크윙에게 가져가야 합니다."}},
[6365] = {"오그리마로 고기 배달", {"자르그의 고기를 크로스로드에 있는 데브락에게 가져가야 합니다."}},
[6381] = {"새로운 생명", {"가이아 흙더미에 가이아 씨앗 10개를 심은 후, 마력 깃든 가이아 씨앗을 가지고 해바위 야영지에 있는 탐라에게 돌아가야 합니다."}},
[6382] = {"잿빛 골짜기 사냥 대회", {"잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다."}},
[6383] = {"잿빛 골짜기 사냥 대회", nil},
[6384] = {"오그리마로 날아가기", {"와이번 조련사 데브락에게 요금을 치르고 오그리마까지 가서 자르그의 고기를 그리쉬카에게 배달해야 합니다."}},
[6385] = {"와이번 조련사 도라스", {"그리쉬카의 편지를 오그리마에 있는 도라스에게 가져가야 합니다."}},
[6386] = {"크로스로드로 돌아가기", {"와이번 조련사 도라스에게 요금을 치르고 크로스로드까지 간 다음 그리쉬카의 편지를 자르그에게 전달해야 합니다."}},
[6387] = {"명예의 곡괭이", {"브록의 목록을 텔사마에 있는 토르그룸 보렐손에게 가져가야 합니다."}},
[6388] = {"그리스 서든", {"명예의 곡괭이를 들고 아이언포지에 있는 그리스 서든에게 가야 합니다."}},
[6391] = {"아이언포지로 날아가기", {"그리핀 조련사 토르그룸 보랠손에게 요금을 내고 아이언포지까지 간 다음 브록의 목록을 골니르 보울더토에게 가져가야 합니다."}},
[6392] = {"브록에게 돌아가기", {"그리핀 조련사 그리스 서든에게 요금을 치르고 텔사마로 간 다음 명예의 곡괭이를 브록 스톤시커에게 배달해야 합니다."}},
[6393] = {"정령들의 전쟁", {"해바위 야영지에 있는 츄나만에게 발화석 10개를 가져가야 합니다."}},
[6394] = {"타즈릴의 곡괭이", {"타즈릴의 곡괭이를 작업반장 타즈릴에게 돌려주어야 합니다."}},
[6395] = {"말라의 마지막 소원", {"사무엘 핍스를 처치하고 그의 유골을 말라의 묘로 옮긴 다음 수련사제 엘레스에게 돌아가야 합니다."}},
[6401] = {"카야의 생존 소식", {"해바위 야영지에 있는 탐라 윈드필드에게 기쁜 소식을 전해야 합니다."}},
[6421] = {"구릉바위 협곡", {"구릉바위 협곡에 있는 동굴을 탐사한 다음 해바위 야영지에 있는 모르로갈에게 리조나이트 수정 10개를 가져가야 합니다."}},
[6441] = {"사티로스의 뿔", {"사티로스의 뿔 16개를 모아 토막나무 주둔지에 있는 픽셀에게 가져가야 합니다."}},
[6442] = {"조람 해안의 나가", {"조람 해안에 있는 마루카이에게 성난지느러미일족의 머리 20개를 가져가야 합니다."}},
[6461] = {"식탐꾼들", {"말라카진에 있는 젠질라가 동굴이끼 땅거미 10마리와 동굴이끼 독거미 7마리를 처치해달라고 부탁했습니다."}},
[6462] = {"트롤 부적", {"조람가르 전초기지에 있는 미쑤와에게 트롤 부적 8개를 가져가야 합니다."}},
[6481] = {"토석인이여 깨어나라", {"마력 깃든 리조나이트 수정으로 리조나이트 광석을 연 다음 고게로크를 처치해야 합니다. 그를 처치했다는 소식과 마력 깃든 리조나이트 수정을 들고 모르로갈에게 돌아가십시오."}},
[6482] = {"루울에게 자유를", {"루울을 호위해 탈출한 후, 토막나무 주둔지에 있는 야마 스노우후프와 대화하십시오."}},
[6503] = {"잿빛 골짜기 정찰꾼", {"잿빛 골짜기 정찰꾼 9명을 처치한 후 토막나무 주둔지에 있는 쿠레이빈에게 돌아가십시오."}},
[6504] = {"잃어버린 열 두쪽", {"잃어버린 벌목기 조작설명서 열 두쪽을 찾아서 1장, 2장, 그리고 3장으로 합쳐야 합니다. 그런 다음 토막나무 주둔지 근처에 있는 구르다 레이지스카에게 돌려 주어야 합니다."}},
[6521] = {"사악한 동맹", {"사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다."}},
[6522] = {"사악한 동맹", {"작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다."}},
[6523] = {"카야 구출", {"카야 플랫후프를 아파라제 야영지까지 호위한 다음 돌발톱 산맥 남동쪽 가장자리에 있는 마카바 플랫후프에게 소식을 전하러 가야 합니다."}},
[6541] = {"카드라크에게 보고", {"불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오."}},
[6542] = {"카드라크에게 보고", {"불모의 땅 북부의 감시탑에 있는 카드라크에게 보고하십시오."}},
[6543] = {"전쟁노래부족 보고서", {"먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오."}},
[6544] = {"토렉의 공격", {"은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오."}},
[6545] = {"전쟁노래부족 길잡이 최신정보", nil},
[6546] = {"전쟁노래부족 척후병 최신정보", nil},
[6547] = {"전쟁노래부족 정찰병 최신정보", nil},
[6548] = {"침략에 대한 복수", {"그림토템부족 약탈자 8명과 그림토템부족 용병 6명을 처치한 다음 돌발톱 산맥 동남쪽 가장자리에 있는 마카바 플랫후프에게 돌아가야 합니다."}},
[6561] = {"검은심연의 음모", {"황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다."}},
[6562] = {"검은심연의 나락으로...", {"잿빛 골짜기에 있는 제네우 생크리와 대화하십시오."}},
[6563] = {"아쿠마이의 정수", {"잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다."}},
[6564] = {"고대 신들에 대한 충성", {"축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오."}},
[6565] = {"고대 신들에 대한 충성", {"검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오."}},
[6571] = {"전쟁노래부족 보급품", {"토막나무 주둔지의 록케 오카르를 위해 전쟁노래부족 보급품을 모아 오십시오. 전쟁노래부족 톱날, 전쟁노래부족 도끼 상자, 전쟁노래부족 기름, 그리고 벌목용 밧줄을 가져와야 합니다."}},
[6581] = {"전쟁노래부족 톱날", nil},
[6607] = {"낚시의 달인 내트 페이글", {"아래 물고기들을 모두 잡아 내트 페이글에게 돌아가야 합니다.","","슬픔의 늪의 안개갈대 해안에 사는 안개갈대 황새치","","잊혀진 땅의 살데리스 해안에 사는 살데리스 아귀","","페랄라스의 베르단티스 강에 사는 페랄라스 참치","","가시덤불 골짜기의 폭풍 해안에 사는 폭풍 해안 푸른도루묵","","위 물고기를 모두 얻은 후 내트 페이글에게 돌아가십시오."}},
[6610] = {"조개 별미", {"더지 퀵클레이브가 다음 재료를 구해 오라고 합니다.","","거대한 알 12개... 타나리스에 떠돌고 있는 로크와 같은 커다란 새에게서 구할 수 있습니다.","","고소한 조갯살 10개... 조개를 열어서 찾을 수 있습니다.","","알터랙 스위스 치즈 20개... 아무 상인이나 붙잡고 알아보십시오.","","모든 재료를 모아서 더지에게 돌아가야 합니다."}},
[6611] = {"가젯잔으로 출발!", {"타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다."}},
[6612] = {"내가 아는 고블린", {"타나리스 사막에 있는 가젯잔으로 가서 더지 퀵클레이브를 만나 당신의 요리 실력 향상에 대해 대화를 나누어야 합니다."}},
[6621] = {"썩은나무일족의 왕", {"썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다."}},
[6622] = {"응급 치료", {"응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다.","","부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 부상병들이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다."}},
[6623] = {"호드 응급의학회", {"아라시 고원에 있는 해머폴로 가서 호드 응급의학회의 일원이 되는 방법에 대해 의사 그레고리 빅터와 대화를 나누어야 합니다."}},
[6624] = {"응급 치료", {"응급 붕대로 상처를 치료해서 환자를 구해야 합니다. 환자 6명이 죽기 전에 15명을 구해야 합니다.","","부상자 치료 우선 순위를 기억해야 합니다! 위독한 부상병이 가장 빨리 사망하고 그 다음으로 위태로운 부상병이 사망합니다. 가벼운 부상을 입은 부상병이 제일 늦게 사망하므로 위독한 부상병과 위태로운 부상병을 먼저 구해야 합니다."}},
[6625] = {"얼라이언스 응급의학회", {"먼지진흙 습지대에 있는 테라모어로 가서 얼라이언스 응급의학회의 일원이 되는 방법에 대해 의사 구스타프 밴하우젠과 대화를 나누어야 합니다."}},
[6626] = {"악의 무리", {"가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다."}},
[6627] = {"지혜의 시험", {"브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다."}},
[6628] = {"지혜의 시험", {"파쿠알 핀탈라스의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 파쿠알 핀탈라스는 언더시티에 있을 것입니다."}},
[6629] = {"그룬디히 다크클라우드 처치", {"그룬디히 다크클라우드와 그림토템부족 투사 6명을 처치한 다음 돌발톱 산맥 남동쪽 끄트머리에 있는 마카바 플랫후프에게 돌아가야 합니다."}},
[6641] = {"채찍꼬리 보르샤", {"머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오.","","성공하면 조람가르 전초기지로 돌아와 전쟁노래부족 길잡이에게 채찍꼬리 보르샤의 죽음을 보고하십시오."}},
[6661] = {"깊은굴 지하철 쥐떼 소탕", {"쥐잡는 사나이의 피리를 사용해 깊은굴쥐 5마리를 잡은 후 몬티에게로 데리고 가야 합니다. 다 끝난 후에는 피리를 몬티에게 되돌려줘야 합니다."}},
[6662] = {"우리 형 닙시", {"스톰윈드 깊은굴 지하철에 있는 닙시에게 이상한 고기 상자를 가져다 주어야 합니다."}},
[6681] = {"라벤홀트 장원", {"힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.","","라벤홀트 장원의 입구 근처에서 자신의 실력을 증명할 상자를 발견하게 될 것이며 어떤 기술을 사용하여 이를 증명해야 할지 준비해야 합니다."}},
[6701] = {"비밀결사대 문장", nil},
[6761] = {"새로운 미개척지", {"다르나서스의 세나리온 자치령에 있는 마스렌길 베어워커와 대화하십시오."}},
[6762] = {"라빈 사투르나", {"달의 숲, 나이트헤이븐에 있는 라빈 사투르나와 대화하십시오. 달의 숲은 악령의 숲과 여명의 설원 사이에 있으며 나무구렁 요새에서 나가는 길을 따라가면 됩니다."}},
[6921] = {"폐허 사이로", {"잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다."}},
[6922] = {"군주 아쿠아니스", {"잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."}},
[6981] = {"빛나는 조각", {"톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오.","","그에게 지시를 받아, 빛나는 조각을 전달해야 합니다."}},
[7003] = {"변형된 거인", {"페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 15개를 가져가야 합니다."}},
[7028] = {"뒤틀린 악마", {"트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다."}},
[7029] = {"바일텅의 타락", {"마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.","","오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.","","녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다."}},
[7044] = {"마라우돈의 전설", {"<name>레브라스의 홀 조각인 <name>레브리안 마법봉과 <name>레브리안 다이아몬드를 찾아야 합니다.","","<name>레브라스와 대화를 나눌 방법을 찾아야 합니다."}},
[7046] = {"셀레브라스의 홀", {"회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.","","의식을 마친 후 그와 대화하십시오."}},
[7064] = {"대지와 씨앗의 오염", {"공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다."}},
[7066] = {"생명의 씨앗", {"달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다."}},
[7067] = {"추방자의 지시서", {"추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다."}},
[7068] = {"음영석 조각", {"마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다."}},
[7070] = {"음영석 조각", {"마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다."}},
[7142] = {"알터랙의 전투", {"알터랙 계곡으로 진입하여 얼라이언스 사령관인 반다르 스톰파이크를 처치하고, 알터랙 산맥에 있는 보그가 데스그립에게 돌아가야 합니다."}},
[7161] = {"신병 계급장", {"알터랙 계곡의 서리늑대 요새 남동쪽에 위치한 자갈발 동굴로 가서 서리늑대부족 깃발을 찾아 전투대장 락그론드에게 가져가야 합니다."}},
[7241] = {"서리늑대부족 수호", {"알터랙 산맥에 있는 알터랙 계곡으로 가십시오. 입구 바깥에 서 있는 전투대장 락그론드를 찾아 서리늑대부족 병사로서의 경력을 쌓도록 하십시오. 알터랙 계곡은 타렌 밀농장 북쪽의 알터랙 산맥 기슭에 있습니다."}},
[7261] = {"칙명", nil},
[7321] = {"독특한 거북이 비스크", {"타렌 밀농장에 있는 크리스토프 제프코트에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다."}},
[7342] = {"화살 거래", nil},
[7383] = {"대지의 왕관", {"자수정 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다."}},
[7492] = {"모자케 야영지", {"페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오."}},
[7494] = {"페더문 요새", {"페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화하십시오."}},
[7541] = {"호드를 위한 활약", nil},
[7701] = {"현상수배: 감독관 말토류스", {"이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다."}},
[7721] = {"변환을 위한 연료", {"페랄라스의 잊혀진 해안에 있는 바다 정령과 바다 물보라 정령에게서 물의 정령 핵 10개를 모아 부두 근처에 있는 조브린 팬대즐에게 가져가야 합니다."}},
[7722] = {"불꽃 융해촉진제?", {"용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다."}},
[7723] = {"두꺼운 손가락의 슬픔", {"이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}},
[7724] = {"뒤꽁무니에서 불을 뿜는 거미", {"이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다.","","불타는 용암거미를 충분히 처치한 후에는 이글거리는 협곡에 있는 한셀 헤비핸드에게 가야 합니다."}},
[7727] = {"인센도사우루스라니 무슨...", {"용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}},
[7728] = {"도난품: 가열로 바람구멍 및 감시병의 망원경", {"이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다.","","이 물건들에 대해 가지고 있는 유일한 정보는 다음과 같습니다.","","검은무쇠 드워프들이 훔쳐간 것이 분명합니다.","가열로 바람구멍은 대장장이들이 사용하는 대장 도구입니다.","감시병의 망원경은 감시병들에게 값으로 따질 수 없을 만큼 중요한 감시 도구입니다."}},
[7729] = {"구인광고: 경쟁 선별", {"검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다."}},
[7730] = {"주크애쉬 출몰", {"페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다."}},
[7731] = {"채찍쐐기", {"고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다."}},
[7732] = {"주크애쉬 보고서", {"오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다."}},
[7734] = {"품질 향상", {"페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다."}},
[7738] = {"완전한 설인 가죽", {"페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다."}},
