[7815] = {"무쇠턱바다거북 처치", {"무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다."}},
[7816] = {"감메리타 처치", {"감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.","","카툼이 감메리타는 해안에서 다른 거북들과 함께 있다고 얘기해 줬습니다."}},
[7820] = {"양모 옷감 기부", nil},
[7821] = {"비단 옷감 기부", nil},
[7826] = {"양모 옷감 기부", nil},
