[7828] = {"은빛갈기늑대 추적", {"긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.","","마코르가 이 늑대들은 동부 내륙지의 황야에 숨어 있다고 얘기해 줬습니다."}},
[7829] = {"포악한 올빼미야수 사냥", {"포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다.","","마코르가 포악한 올빼미야수는 동부 내륙지의 황야에 서식한다고 얘기해 줬습니다."}},
[7830] = {"트롤의 복수", {"우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다.","","마코르의 얘기로는 우두머리 뾰족부리그리핀은 주로 동부 내륙지의 황야에 서식하는 희귀종이라고 합니다."}},
[7833] = {"양모 옷감 기부", nil},
