[7839] = {"썩은가지부족 불량배", {"동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다.","","대장장이 슬래그트리의 말에 의하면 그 도구들은 동부 내륙지의 북동쪽 지역에 있는 썩은가지부족 신전들 중 하나에 있을 것이라고 얘기했으며 굼벵이 바위굴도 조사해 보는 것이 좋겠습니다."}},
[7840] = {"잃어버린 라드의 점심", {"동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니<name>.","","라드가 점심을 북쪽에 있는 섬에 두고왔<name>고 했습니<name>. 썩은가지부족 트롤을 조심하십시오."}},
[7841] = {"첫 번째 통첩장", {"깊은골짜기 길잡이 15명, 깊은골짜기 정찰대 15명, 깊은골짜기 명사수 15명, 그리고 깊은골짜기 순찰대 15명을 처치한 후 동부 내륙지의 레반터스크 마을에 있는 오토 모지코에게 돌아가야 합니<name>.","","깊은골짜기 하이 엘프들은 동부 내륙지 북서쪽 지역에 있는 쿠엘<name>닐 오두막에 있습니<name>."}},
[7842] = {"또 다른 통첩장", nil},
[7844] = {"동족을 잡아먹는 사촌", {"썩은가지부족 무두장이 30명과 썩은가지부족 예언자 15명을 처치하고 동부 내륙지의 레반터스크 마을에 있는 비술사 야요진에게 돌아가야 합니다.","","야요진은 이 트롤들이 동부 내륙지의 북동부 지역에 있는 샤올와타 및 아골와타 신전 근처에 있다고 가르쳐 주었습니다."}},
[7845] = {"납치된 장로 쏜터스크!", {"동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니<name>.","","장로 쏜터스크는 동부 내륙지의 남쪽에 위치한 썩은가지부족의 수도인 진타알로의 꼭대기에 갇혀 있<name>고 합니<name>."}},
[7846] = {"열쇠를 찾아서", {"수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다."}},
[7847] = {"주술사 쏜터스크에게로", {"장로 쏜터스크가 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가서 자신이 진타알로에서 풀려났다는 사실을 전해 달라고 부탁했습니다."}},
[7849] = {"동생의 유골", {"레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니<name>.","","마코르가 말하기를 썩은가지부족의 수액괴물과 늑대들이 동생의 유골을 훼손하고 있<name>고 합니<name>. 또한 진타알로의 신전 근처에는 수액괴물이 가득한 쓰레기 폐허와 늑대 우리가 있<name>고 합니<name>."}},
[7850] = {"어둠의 용기", {"진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니<name>."}},
[7861] = {"현상 수배: 타락한 여사제 헥스와 그녀의 부하", {"타락한 여사제 헥스와 썩은가지부족 아만자시 경비병 20명을 해치운 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크와 대화해야 합니<name>.","","동부 내륙지의 진타알로 꼭대기에 가면 타락한 여사제 헥스와 아만자시 경비병을 찾을 수 있습니<name>."}},
[7862] = {"구인광고: 레반터스크 마을의 경비대장", {"썩은가지부족 광전사 20명, 썩은가지부족 어둠사냥꾼 20명, 썩은가지부족 혈투사 20명, 썩은가지부족 영혼사냥꾼 20명을 처치한 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가야 합니<name>."}},
