[8365] = {"최신 유행 해적 모자", {"타나리스의 스팀휘들 항구에 있는 거만한 의류상의 부탁으로 남쪽바다 해적 모자 20개를 모아서 가져가야 합니다."}},
[8366] = {"남쪽바다해적단 처리반", {"타나리스의 스팀휘들 항구에 있는 보안과장 빌지위즐이 남쪽바다해적단 무법자, 약탈자, 부두일꾼, 칼잡이를 각각 10명씩 처치해 달라고 부탁했습니다."}},
[8368] = {"전쟁노래 협곡 전투", {"전장 밖에 있는 호드 전쟁인도자에게 전쟁노래 협곡 명예 훈장 3개를 가져가야 합니다."}},
