[92834] = {"원한은 열 배로 갚는다", {"강풍딸기 지대에 있는 발라나르 북쪽 혹은 아키르 사당의 알아케스 이교도에게서 알아케스 바람석 부적 10개를 입수해야 합니다."}},
[92840] = {"바람을 붙잡다", {"색인 에소테리아를 셴다르 고원의 전망대 입석으로 가져가 주변의 바람석 결정체에 사용해 자료를 수집해야 합니다."}},
[92849] = {"사라진 학자", {"계속 필리온 플레임브리즈를 찾아야 합니다."}},
[92850] = {"사라진 학자", {"괴성조 소굴에서 괴성조 어미를 처치하고 그 머리를 발라나르에 있는 필리온 플레임브리즈에게 가져가야 합니다."}},
[92860] = {"제프라스를 위하여", {"발레니아 스톰피스트를 찾아가 고등 마법원이 알아케스와의 싸움에 동참할 것이라고 알려야 합니다."}},
[92867] = {"지켜 낼 터전", {"스트롬가드 요새에 침입한 돌주먹 일족, 비밀결사대, 마른나무껍질 부족을 처치하고 관리인 로마르에게 가야 합니다."}},
[92871] = {"제프라스를 위하여", {"발레니아 스톰피스트를 찾아가 바람구체자가 알아케스와의 싸움에 동참할 것이라고 알려야 합니다."}},
[92872] = {"책임을 향한 발걸음", {"무덤 가루 주머니를 대해에 던진 후, 스트롬가드 요새 납골당에 있는 관리인 알라리크에게 가야 합니다."}},
[92878] = {"말을 잃다", {"나미다 그림토템의 최후를 증명할 물건을 모자케 야영지의 블라이즈 몽고메리에게 가져가야 합니다."}},
[92880] = {"발라나르로의 귀환", {"요르나의 보고를 발라나르에 있는 발레니아 스톰피스트에게 가져가야 합니다."}},
[92881] = {"대장로의 요청", {"발라나르에서 탈라니스 섀도송과 대화해야 합니다."}},
[92909] = {"수확기를 수확하라", {"살딘 농장의 오즈윈 아이언스프로킷에게 골렘 등가용수철 14개와 허수아비골렘 회전안정기 5개를 가져가야 합니다."}},
[92910] = {"수확기를 수확하라", {"전진식 자동인지 조립체를 살딘 농장에 있는 오즈윈 아이언스프로킷에게 가져가야 합니다."}},
[92911] = {"수확기를 수확하라", {"살딘 농장의 오즈윈 아이언스프로킷에게 골렘 등가용수철 8개, 구리 변조기 4개, 조잡한 조준경을 가져가야 합니다."}},
[92914] = {"이상한 수정탑", {"셴드랄라스를 탐사하며 전에 발견한 것과 같은 수정탑을 더 찾아야 합니다."}},
[92947] = {"움직일 때", {"알아케스 수호자 7명, 알아케스 영혼소환사 7명, 알아케스 검귀 7명을 처치한 후 아키르 사당에 있는 휴사 퀵브리즈에게 보고해야 합니다."}},
[93016] = {"간략한 역사 수업", {"셴드랄라스에 있는 모덴트 이븐셰이드와 대화해 복구한 수정에 관한 정보를 얻어야 합니다."}},
[93034] = {"뼈의 골짜기", {"겔키스에 대한 평판을 올리는 한편, 겔키스 마을 동쪽 멀리 있는 뼈의 골짜기 근처에서 네를로크를 찾아야 합니다."}},
[93035] = {"날뛰는 약탈자들", {"겔키스와 우호적인 평판을 유지하면서 언데드 약탈자 6명을 처치하고, 그런 다음 뼈의 골짜기 남쪽 입구에 있는 네를로크에게 가야 합니다."}},
[93036] = {"이교도 잠입", {"셴다르 마을에서 사니아 실버스트림과 대화해야 합니다."}},
[93037] = {"추방자의 민낯", {"겔키스와 우호적인 평판을 유지하면서, 뼈의 골짜기 입구에 있는 네를로크에게 강령술사의 의복 1개를 가져가야 합니다."}},
[93041] = {"진실과 마주할 때", {"겔키스와 우호적인 평판을 유지하면서, 겔키스 마을에 있는 현자 우텍에게 저주받은 해골과 겔키스일족 강령술사의 의복을 가져가야 합니다."}},
[93044] = {"정화의 외침", {"겔키스와 우호적인 평판을 유지하면서, 겔키스 마을에 있는 현자 우텍에게 테라드라스의 눈물을 가져가야 합니다."}},
[93045] = {"이론 검증", {"겔키스와 우호적인 평판을 유지하면서, 저주받은 해골에 있는 강령술 저주를 해제해야 합니다. 성공한 후에는 뼈의 골짜기 근처에 있는 네를로크에게 보고해야 합니다."}},
[93058] = {"동족 구하기", {"겔키스와 우호적인 평판을 유지하면서, 뼈의 골짜기에 있는 겔키스일족 포로 5명을 구출해야 합니다. 임무를 완료한 후, 입구 근처에 있는 네를로크에게 가야 합니다."}},
[93062] = {"해골 매장", {"겔키스와 우호적인 평판을 유지하면서, 뼈의 골짜기 곳곳에 있는 실패한 소환수 8마리의 저주를 해제해야 합니다."}},
[93065] = {"전투 준비", {"강풍딸기 저지대에서 발레니아 스톰피스트와 대화해야 합니다."}},
[93089] = {"다가오는 미래", {"제프라스 섬을 떠날 준비를 마치고 엘라드린 에벤게일과 대화해야 합니다."}},
[93090] = {"다가오는 미래", {"제프라스 섬을 떠날 준비를 마치고 아에사 돈싱어와 대화해야 합니다."}},
[93122] = {"동태 살피기", {"겔키스와 우호적인 평판을 유지하면서, 셴드랄라스 내부에 있는 켄타우로스 관심 지점을 조사해야 합니다. 그런 다음 뼈의 골짜기 입구에 있는 네를로크에게 알아낸 사항을 보고해야 합니다."}},
[93125] = {"집으로 가는 길", {"겔키스와 우호적인 평판을 유지하면서, 로크렌을 추방자 은신처 밖으로 호위해야 합니다. 그런 다음 뼈의 골짜기 근처에 있는 네를로크에게 무슨 일이 있었는지 알려야 합니다."}},
[93128] = {"칸 젠", {"겔키스와 우호적인 평판을 유지하면서, 마그람 마을에 있는 칸 젠을 처치해야 합니다. 임무를 완수한 후에는 잊혀진 땅 겔키스 마을에 있는 현자 우텍에게 보고해야 합니다."}},
[93159] = {"수상한 은둔자", {"그늘돌풍 숲에서 수상한 은둔자와 대화해 어떤 사람인지 자세히 알아봐야 합니다."}},
[93160] = {"숲이 내린 선물", {"그늘돌풍 숲에서 그늘돌풍 도토리 8개를 채집해야 합니다."}},
[93162] = {"파멸자의 머리", nil},
[93165] = {"자비는 닫힌 귀에 닿지 않는다", {"그늘돌풍 숲, 아키르 사당 혹은 강풍딸기 저지대에 있는 알아케스 이교도에게서 알아케스 이교도의 귀 5개를 입수해야 합니다."}},
[93172] = {"유령 해방", {"그늘돌풍 숲에서 바람의 유령 10명을 처치해야 합니다."}},
[93176] = {"내 작은 친구들", {"초보 곤충학자의 도구에 든 물품을 사용해 수목 타란툴라와 건초 바구미 표본, 살점 야금이를 찾아 잡아야 합니다."}},
[93197] = {"연락 복구", {"하이잘 산 정상 야영지에 있는 세벨리아에게서 소포를 받아 눈망루 마을 여관주인 비지에게 전달해야 합니다."}},
[93224] = {"조각한 켄타우로스 토템", {"잊혀진 땅 전역의 켄타우로스를 처치해 조각한 켄타우로스 토템을 5개 입수한 후, 입수한 토템을 나이젤의 야영지에 있는 대령 펜리가스트에게 제출해야 합니다."}},
[93225] = {"조각한 켄타우로스 토템", {"잊혀진 땅 전역의 켄타우로스를 처치해 조각한 켄타우로스 토템을 5개 입수한 후, 입수한 토템을 침묵의 초소에 있는 구르다 와일드메인에게 제출해야 합니다."}},
[93226] = {"우정은 살 수 있다: 마그람", {"토템 가방을 잊혀진 땅 마그람 마을에 있는 마그람 병참장교에게 가져가 마그람 부족에 대한 평판을 크게 높여야 합니다. 켄타우로스 - 마그람일족과의 평판이 중립적 이상이어야 합니다."}},
[93227] = {"우정은 살 수 있다: 겔키스", {"토템 가방을 잊혀진 땅 겔키스 마을에 있는 겔키스 병참장교에게 가져가 겔키스 부족에 대한 평판을 크게 높여야 합니다. 켄타우로스 - 겔키스일족과의 평판이 중립적 이상이어야 합니다."}},
[93317] = {"게잡이 철", {"바람노래 집게발 고기 6개를 모아야 합니다."}},
