[93429] = {"혈육의 정", {"드레노어 성역에 있는 잃어버린 드레나이 10명을 처치해야 합니다."}},
[93430] = {"미끼를 되찾아라", {"펠루크의 미끼를 훔친 잃어버린 드레나이 난민 낚시꾼을 찾아 미끼를 되찾아야 합니다."}},
[93443] = {"잃어버린 화물 상자", {"잃어버린 화물 상자를 강물터 화약심지 항구에 있는 프리즈 프래즐스파크에게 전달해야 합니다."}},
[93450] = {"환영의 문제", {"빈다엘의 미완성 검을 가져가 영혼계로 인도할 방법을 알아낸 후, 환영의 칼날을 셴드랄라스에 있는 빈다엘에게 돌려줘야 합니다."}},
[93459] = {"알아케스의 귀 더 모으기", nil},
