[93464] = {"피난처를 방문한 마법사", {"잊혀진 땅에서 드레니시스트의 힘에 관해 아는 마법사를 찾아야 합니다."}},
[93465] = {"드레니시스트 연구 기록", {"드레니시스트에 관한 기마쉬의 기록을 수집한 후, 아조레 알다모트에게 가져가야 합니다."}},
