[93594] = {"숲이 전하는 말", {"잊혀진 땅 셴드랄라스에 있는 버려진 정원에서 우드와이어드를 찾아야 합니다."}},
[93601] = {"책임 전가", {"뾰족털일족 은거지에서 지위가 높은 가시멧돼지를 찾아야 합니다."}},
[93604] = {"아감마간의 피", {"가시덩굴 구릉으로 이동해 아감마간의 악성 핏덩이를 입수한 후, 잊혀진 땅 뾰족털일족 은거지에 있는 용감한 코그투그에게 제출해야 합니다. 코그투그의 말에 따르면 가시덩굴 우리에 있는 아감마간의 핏덩이로는 부족하다고 합니다."}},
[93615] = {"어린 고양이 친구들", {"하이잘 산 야생에서 샬라칼의 새끼 고양이를 찾아야 합니다."}},
[93644] = {"너덜너덜한 일지", {"글의 내용을 단서로 셴드랄라스 어딘가에 있는 일지의 저자를 찾아야 합니다."}},
[93663] = {"배송 중 실종", {"실종된 배달부를 찾은 후, 다르의 화물을 피난처로 전달해야 합니다."}},
