[93737] = {"부서진 피조물", {"리아니 나이트윈드를 찾아가 무슨 이야기를 하는지 들어봐야 합니다."}},
[93738] = {"부서진 피조물", {"발라나르에 있는 아에사 돈싱어에게 보고해야 합니다."}},
[93739] = {"호드 연합 둘러보기", {"그롬마쉬 요새에 있는 나즈그렐과 대화하여 추가적인 지시를 받아야 합니다. 받은 지시서에 따라 볼진, 케른 블러드후프, 여군주 실바나스 윈드러너를 찾아 대화해야 합니다."}},
[93740] = {"피에는 피", {"강풍딸기 저지대에 있는 알아케스 이교도의 시체에서 알아케스 바람석 부적 10개를 입수해야 합니다."}},
[93746] = {"단호한 대응", {"아키르 사당으로 가는 길에서 벨라탄 브라이트위시를 대면해야 합니다."}},
[93747] = {"폭력에서 녹음으로", {"망가진 쇠뇌와 망가진 투석기, 망가진 비행기 주변에 마력 깃든 씨앗을 심어야 합니다."}},
[93759] = {"자연이 내린 풍요", {"은둔자의 스튜에 넣을 오염되<name> 않은 하이잘 수사슴에게서 하이잘 사슴고기 조각 2개를, 붉은 독침 덩이줄기 6개를 채집해야 합니다."}},
[93786] = {"피로 쓴 전언", {"풀잎개울에서 풀잎개울 농장 일꾼 12명을 처치하고 크롬로쉬에게 성공 소식을 전해야 합니다."}},
[93787] = {"식량 약탈", {"풀잎개울 얼라이언스 농장에서 먹이 자루 6개를 훔쳐 크롬로쉬에게 가야 합니다."}},
[93788] = {"빌린 검", {"터너의 벌목지에 있는 벌목꾼에게서 로그마의 크레자 다크쏜에게 줄 목공의 도끼 10개를 회수해야 합니다."}},
[93791] = {"벨란과 대화", {"발라나르에서 벨란 윈드우드와 대화해야 합니다."}},
[93797] = {"바람 속의 나뭇가지", {"바람 깃든 나뭇가지를 발라나르에 있는 벨란 윈드우드에게 가져가야 합니다."}},
[93835] = {"로르투나와 대면", {"위쪽 로하시 첨탑으로 통하는 차원문을 사용한 후, 엘라드린 에벤게일과 아에사 돈싱어에게 합류해 대여사제 로르투나를 대면해야 합니다."}},
[93836] = {"제프라스의 운명", {"발라나르에서 탈라니스 섀도송과 대화해야 합니다."}},
[93926] = {"서부 감시터", {"서쪽 감시탑에서 평화감시자 바니엘을 찾아야 합니다."}},
[93927] = {"마지막 부탁", {"평화감시자 시체 주위에서 쪽지를 입수하고, 쪽지를 확인해 다음 계획을 세워야 합니다."}},
[93948] = {"인장 전달", {"섀도송 가문 인장을 발라나르에 있는 탈라니스 섀도송에게 전달해야 합니다."}},
[93949] = {"낮말도 밤말도 벌레가 듣네", {"마력 깃든 하늘폴짝이 8마리를 처치할 때까지 발라나르에서 하늘폴짝이를 처치해야 합니다."}},
[93951] = {"작은 아름다움", {"셴다르 고원에서 히포그리프 잔깃털 8개를 모아야 합니다."}},
[93958] = {"내부 성소", {"아키르 사당의 내부 성소에서 발레니아 스톰피스트와 대화해야 합니다."}},
[93963] = {"얼라이언스 연합 둘러보기", {"스톰윈드 왕궁에 있는 랜들 에머슨과 대화하여 추가적인 지시를 받아야 합니다. 받은 지시서에 따라 국왕 마그니 브론즈비어드, 땜장이왕 멕카토크, 티란데 위스퍼윈드를 찾아 대화해야 합니다."}},
[93976] = {"고블린 상인", {"검을 로그마 동쪽 부두에 있는 크레자 다크쏜의 지인에게 전달해야 합니다."}},
[94003] = {"하늘파괴자 보루 방패", {"아키르 사당의 자알 스톰실드에게서 하늘파괴자 보루 방패를 회수해야 합니다."}},
[94006] = {"위대한 우르세라 정령", {"발라나르 북동쪽 폭포 주위에서 우르센드리스와 대화해야 합니다."}},
[94007] = {"야수 길들이기", {"발라나르에 있는 퀠라나 퀵게일에게 보고해야 합니다."}},
[94013] = {"야수 길들이기", {"강풍딸기 저지대에서 조련용 막대를 사용해 벌드렌 우두머리를 길들여야 합니다. 기술을 연습한 후 발라나르에 있는 퀠라나 퀵게일에게 조련용 막대를 돌려주어야 합니다."}},
[94050] = {"야수 길들이기", {"발라나르에서 퀠도라 퀵게일과 대화해야 합니다."}},
