[97130] = {"고대 구루바시의 비밀", {"가라앉은 도시에서 고대 구루바시 우상을 회수해야 합니다."}},
[97170] = {"탈것 타기 배우기", {"랜들 헌터에게 초급 타기를 배워야 합니다."}},
[97194] = {"탈것 타기 배우기", {"킬다르에게 초급 타기를 배워야 합니다."}},
[97196] = {"혹한의 눈", {"가시덩굴 구릉에서 혹한의 눈을 회수해야 합니다."}},
[97197] = {"불의 땅의 파편", {"검은바위 나락에서 불의 땅의 파편을 회수해 멀고어에 있는 알라나 스톰워커에게 전달해야 합니다."}},
[97198] = {"검은아귀 마법", {"검은아귀 요새에서 검은아귀 의식 토템을 회수해야 합니다."}},
[97200] = {"탈것 타기 배우기", {"살티에게 초급 타기를 배워야 합니다."}},
[97203] = {"탈것 타기 배우기", {"벨마 워넘에게 초급 타기를 배워야 합니다."}},
[97205] = {"탈것 타기 배우기", {"겐 페어웨더를 통해 초급 타기를 배워야 합니다."}},
[97220] = {"필모어의 부탁", {"경비소 화물을 상업 지구 트리아스 치즈 상점에 있는 창고 입구로 가져가야 합니다."}},
[97222] = {"경비소 물품", {"경비소 화물을 트리아스의 상점 위층으로 옮긴 뒤, 문 바깥에 둬야 합니다."}},
[97223] = {"붉은발톱랩터 어미", {"붉은발톱랩터 어미의 알을 센진 마을에 있는 살티에게 가져가야 합니다."}},
[97225] = {"잊힌 로아 우상", {"메아리 섬에서 잊힌 로아 우상 8개를 모아 센진 마을에 있는 장로 가드린에게 가져가야 합니다."}},
[97234] = {"독서실", {"포장된 읽을거리를 스톰윈드 도서관으로 가져가야 합니다."}},
[97236] = {"기시이스의 송곳니", {"기시이스의 송곳니를 알드랏실에서 거미 연구에 관심을 보일 만한 사람에게 가져가야 합니다."}},
[97237] = {"서가에서 골라 담기", {"도서관 어딘가에 있는 각 읽을거리를 찾은 뒤, 스톰윈드 공원에 있는 로이 르웰스에게 가야 합니다."}},
[97242] = {"옐마크의 특별 배합", {"명예의 골짜기 물가에 자라는 부들과 창풀의 꺾꽂이를 채취한 후, 옐마크의 연금술용품점에 있는 코르겔드에게 가야 합니다."}},
[97243] = {"불의 부름", {"희미한 불씨의 횃불을 강풍딸기 저지대 불꽃의 제단에 있는 올라리안 스위프트번에게 가져가야 합니다."}},
[97244] = {"불의 부름", {"강풍딸기 저지대에서 하늘사제 팔라디엘을 처치하고 팔라디엘의 심장을 획득해야 합니다."}},
[97245] = {"불의 부름", {"셴다르 고원에서 쿠라마의 거처를 찾은 후, 쿠라마의 영혼과 싸워 쓰러뜨려야 합니다. 승리한 후 쿠라마의 가면을 강풍딸기 저지대에 있는 올라리안 스위프트번에게 전달해야 합니다."}},
[97246] = {"밥보다 놀이", {"보르스탄의 아궁이로 가서 타토그가 미기의 도시락을 미기에게 직접 전해 달라고 했다고 보르스탄에게 말해야 합니다."}},
[97249] = {"제일 좋아하는 음식", {"미기의 도시락을 그롬마쉬 요새 뒤편에 있는 미기에게 가져가야 합니다."}},
[97250] = {"억울한 누명, 정당한 응징", {"먼지진흙 습지대와 맞닿은 불모의 땅 국경을 침범한 얼라이언스 병사들을 처치한 후, 타우라조 야영지에 있는 그런트 로그마르에게 가야 합니다."}},
[97253] = {"부품이 산산조각", {"톱니항 남부의 해적 야영지 상부에서 복잡한 부품 한 줌 5개를 모은 후 톱니항에 있는 비운의 레닉스에게 가야 합니다."}},
[97257] = {"불의 부름", {"올라리안이 공물의 화로에서 의식을 시작할 때까지 기다린 후, 올라리안의 지시를 따라야 합니다.","","제한 시간이 만료되기 전에 영원의 불꽃을 발라나르로 전달해야 합니다."}},
[97263] = {"소포가 도착했습니다", {"잘못 놓인 엘드룬의 소포를 전달해야 합니다."}},
[97265] = {"서릿발분노를 증오하라", {"잊혀진 땅의 살게론에서 여러 종류의 서릿발분노의 사티로스를 처치한 후, 그늘수렵 마을에 있는 아카라이에게 가야 합니다."}},
[97275] = {"뭐가 그리 급해", {"옐마크의 물약을 우트에게 건네야 합니다."}},
[97277] = {"그룬드와 고즈윈", {"북서쪽 언덕에서 그룬드와 고즈윈의 야영지를 찾아야 합니다. 고즈윈의 정비사 일지를 회수하고 눈표범 배회자를 처치해야 합니다."}},
[97279] = {"주인 잃은 무기", {"버려진 훈련용 무기 6개를 모은 후, 동굴 막사에 있는 크잔 손슬래시에게 가야 합니다."}},
[97281] = {"들끓는 폭풍", {"희미한 폭풍 보주를 모래바람 협곡 근처에 있는 레즐락에게 가져가야 합니다."}},
[97282] = {"폭풍을 품은 잠재력", {"충만한 천둥도마뱀 장기 5개를 모래바람 협곡 근처에 있는 레즐락에게 가져가야 합니다."}},
[97284] = {"발라리엘의 복수", {"잊혀진 땅의 천둥도끼 요새에서 불타는 칼날단 오크를 처치한 후, 나이젤의 야영지에 있는 발라리엘 데몬슬레이어에게 가야 합니다."}},
[97286] = {"연구 자료 열람 허가", nil},
[97287] = {"영리한 협상", {"달라란 근처에 있는 대마법사 모데라의 환영과 대화해야 합니다."}},
[97288] = {"끝없는 고통", {"흉측한 머리를 언더시티에 있는 수석 연금술사 파라넬에게 전달해야 합니다."}},
[97289] = {"끝없는 고통", {"남작의 머리카락을 언더시티에 있는 오스마르의 몸으로 가져가야 합니다."}},
[97290] = {"끝없는 고통", {"알아낸 정보를 언더시티에 있는 수석 연금술사 파라넬에게 보고해야 합니다."}},
[97291] = {"끝없는 고통", {"언더시티의 수석 연금술사 파라넬을 위해 상업 지구에 있는 타우니 그리제트에게서 유독한 해골갓을, 전문 약초채집사 근처에서 물집풀을, 도적 지구 독 상인에게서 괴로움의 정수를 입수해야 합니다."}},
[97292] = {"끝없는 고통", {"수석 연금술사 파라넬이 말한 대로 오스마르의 몸 위 장치에 쉭쉭거리는 혈청을 주입해야 합니다."}},
[97326] = {"바위 쉼터", {"그롬마쉬 요새 뒤편에 있는 트라에게 매끈한 바위 8개를 가져가야 합니다."}},
[97328] = {"돈 될 만한 물건", {"가시덤불 골짜기 줄쿤다의 폐허에서 도난당한 화물 8개를 회수한 후, 무법항에 있는 누군가에게 반환해야 합니다."}},
[97329] = {"열쇠는 어디에?", {"가시덤불 골짜기 줄쿤다의 폐허에 있는 트롤에게서 원시 열쇠를 입수한 뒤 지믹스 스퍼터스파크에게 가져가야 합니다."}},
[97331] = {"지믹스의 대탈출", {"지믹스 스퍼터스파크를 줄쿤다의 폐허 밖으로 호위한 뒤, 무법항에 있는 부두주임 로즈길에게 구출 성공 소식을 전해야 합니다."}},
[97332] = {"두 번 어긋난 믿음", {"두 번 재주문된 소포를 강물터 화약심지 항구에 있는 부두장 위즈버즈에게 가져가야 합니다."}},
[97378] = {"거울비늘", {"거울비늘의 날개를 썬더 블러프에 있는 멜로르 스톤후프에게 가져가야 합니다."}},
[97386] = {"그롬골 공격", {"그롬골 주둔지의 사령관 아그로고쉬를 위해 모쉬오그 오우거 소굴의 오우거를 처치해야 합니다."}},
[97453] = {"잡초 제거", {"그롬골 남쪽에서 식충 잡초 6마리를 처치하고 젬밀의 어머니에게 알려야 합니다."}},
[97485] = {"썬더 블러프의 전통", {"약초채집사 니다에게서 약초 묶음을, 마법부여용품 상인 나타에게서 삼나무 가지 묶음을, 가죽세공용품 상인 마후에게서 힘줄 실타래를, 요리용품 상인 나알에게서 의식용 부싯돌과 불쏘시개를 구매해야 합니다.","","재료를 조합한 후 수렵의 봉우리 가장자리에서 향을 흩뿌려야 합니다."}},
[97530] = {"모래망치의 빚", {"타나리스 스팀휘들 항구의 보안과장 빌지위즐을 위해 모래망치 오우거 주둔지 근처에서 잃어버린 유난히 반짝이는 팔찌를 회수해야 합니다."}},
[97534] = {"모래밭의 뒷거래", {"사막 잔해 7개를 회수한 후, 가젯잔에 있는 쿠인에게 가야 합니다."}},
[97536] = {"노움 쓰레기", {"타나리스 사막에서 가젯잔과 다른 폐기물로부터 충분히 떨어진 지점에 방사성 폐기물 상자를 버린 후, 조르디 랩포지에게 가야 합니다."}},
[97538] = {"그림을 물들일 안료", {"땅거미 호수에서 땅거미풀 깍지 30개를 구해 썬더 블러프에 있는 타흐 윈터후프에게 가져가야 합니다."}},
[97539] = {"비단결 봉합사", {"아라시 고원 해머폴에 있는 의사 그레고리 빅터에게 외과용 거미줄 12개를 가져가야 합니다."}},
[97540] = {"오아시스", {"갈증을 해소한 투가를 아내 토르타에게 데려다줘야 합니다."}},
[97558] = {"포세이큰을 위한 가죽", {"셸렌 로바트에게 그늘박쥐 날개막 8개, 암흑사냥개 가죽 6개, 썩은지느러미 멀록 가죽 3개를 가져가야 합니다."}},
[97617] = {"안전 점검", {"연구되지 않은 유물 8개와 탐험가 연맹 채굴용 안전모, 온전한 곡괭이를 찾아서 모단 호수와 황야의 땅 경계에 있는 도르가론에게 가져가야 합니다."}},
[97663] = {"보급품과 연구 자료", {"먼지받이에 있는 오우거를 처치해 무스할레의 도난당한 보급품을 되찾고, 이를 사용해 주변 돌 각인의 탁본을 뜬 후 카르가스에 있는 무스할레에게 가야 합니다."}},
[97821] = {"신기루 거울", {"황야의 땅에서 이 발견에 관심을 보일 만한 사람을 찾아야 합니다."}},
[97884] = {"햇살숲의 무기고", {"강물터의 햇살숲으로 이동해 트레메인 가문의 대장기술 비법서를 회수해야 합니다."}},
[97891] = {"물약 특급 배송", {"제한 시간 안에 불안정한 물약을 연금술 실험실의 박사 마틴 펠벤에게 가져가야 합니다."}},
[97894] = {"아우버다인의 사업", {"어둠의 해안 아우버다인에 있는 골볼트 스틸핸드를 찾아가야 합니다.","","보르구스의 말에 따르면 스톰윈드 항구 최남단 부두에 아우버다인까지 데려다줄 배가 있다고 합니다."}},
[97900] = {"캠핑 입문: 대장기술", {"칼바위 언덕에서 드우크와 대화하여 현재 전문 기술로 만들 수 있는 캠핑 장비의 제작법을 배워야 합니다. 단, 충분한 숙련도를 달성했음을 증명해야 합니다."}},
