[97904] = {"캠핑 입문: 낚시", {"센진 마을 근처에서 라우티키와 대화하여 현재 전문 기술로 만들 수 있는 캠핑 장비의 제작법을 배워야 합니다. 단, 충분한 숙련도를 달성했음을 증명해야 합니다."}},
[97905] = {"캠핑 입문: 약초채집", {"오그리마에서 잔디와 대화하여 현재 전문 기술로 만들 수 있는 캠핑 장비의 제작법을 배워야 합니다. 단, 충분한 숙련도를 달성했음을 증명해야 합니다."}},
